package com.example

/**
 * Domain 9: Constitutional Reforms, Independence Movement, World Wars & Modern Sri Lanka
 * (මැකලම්, මැනිං, ඩොනමෝර්, සෝල්බරි ආණ්ඩුක්‍රම, සර්වජන ඡන්දය, නිදහස, ලෝක යුද්ධ, 1972 හා 1978 ආණ්ඩුක්‍රම)
 * Clean Sinhala questions aligned with syllabus. NO lesson title prefixes.
 */
object HistoryLiveExamModernConstBank {
  private val T = HistoryTopicDomain.MODERN_CONSTITUTIONAL

  private fun q(
    topic: HistoryTopicDomain,
    stem: String,
    correct: String,
    distractor1: String,
    distractor2: String,
    distractor3: String,
    explanation: String
  ): HistoryCuratedQuestion {
    return HistoryCuratedQuestion(
      stem = stem,
      options = listOf(correct, distractor1, distractor2, distractor3),
      correctIndex = 0,
      explanation = explanation,
      topic = topic
    )
  }

  fun constitutionalModernAndWorldWarsQuestions(): List<HistoryCuratedQuestion> = listOf(
    q(T, "ශ්‍රී ලංකාවේ ව්‍යවස්ථාදායක සභාවට ප්‍රථම වරට සීමිත ඡන්ද බලයෙන් මන්ත්‍රීවරයෙකු තෝරාපත් කරගැනීමට අවස්ථාව දුන් ආණ්ඩුක්‍රමය කුමක්ද?", "1910 මැකලම් ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණය (McCallum Reforms)", "කෝල්බෲක් ආණ්ඩුක්‍රමය", "මැනිං ආණ්ඩුක්‍රමය", "ඩොනමෝර් ආණ්ඩුක්‍රමය", "උගත් ලාංකිකයන්ට සීමිත ඡන්ද බලයක් හිමිවූ 'උගත් ලාංකික ආසනය' (Educated Ceylonese Seat) මැකලම් ආණ්ඩුක්‍රමය මගින් හඳුන්වා දෙන ලදී."),
    q(T, "1911 දී පැවති උගත් ලාංකික ආසනය සඳහා වූ ප්‍රථම ඡන්ද විමසීමේදී වෛද්‍ය මාකස් ප්‍රනාන්දු පරාජය කරමින් ජයග්‍රහණය කළ නායකයා කවුද?", "ශ්‍රීමත් පොන්නම්බලම් රාමනාදන් (Sir Ponnambalam Ramanathan)", "ශ්‍රීමත් ජේම්ස් පීරිස්", "ඩී. ඇස්. සේනානායක", "ඊ. ඩබ්ලිව්. පෙරේරා", "සිංහල හා දෙමළ උගතුන්ගේ සහයෝගයෙන් පොන්නම්බලම් රාමනාදන්තුමා උගත් ලාංකික නියෝජිතයා ලෙස තේරී පත් විය."),
    q(T, "ශ්‍රී ලංකාවේ ව්‍යවස්ථාදායක සභාවට මුල්වරට 'ප්‍රාදේශීය නියෝජන ක්‍රමය' (Territorial Representation) හඳුන්වා දුන් ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණය කුමක්ද?", "1920 මැනිං ආණ්ඩුක්‍රමය (Manning Reforms)", "මැකලම් ආණ්ඩුක්‍රමය", "කෝල්බෲක් ආණ්ඩුක්‍රමය", "සෝල්බරි ආණ්ඩුක්‍රමය", "වාර්ගික නියෝජනයට අමතරව දිස්ත්‍රික් සහ පළාත් පදනම් කරගත් ප්‍රාදේශීය ආසන 11 ක් මැනිං ආණ්ඩුක්‍රමය මගින් ඇති කරන ලදී."),
    q(T, "1924 මැනිං-ඩෙවොන්ෂයර් ආණ්ඩුක්‍රමයේ පැවති ප්‍රධානතම ව්‍යවස්ථාපිත දුර්වලතාව කුමක්ද?", "ව්‍යවස්ථාදායක සභාවේ නිලනොලත් බහුතරයක් සිටියද ආණ්ඩුවේ විධායක බලය ආණ්ඩුකාරවරයා සතුවීම (වගකීම් විරහිත නියෝජිත ආණ්ඩුව)", "ඡන්ද අයිතිය නොතිබීම", "මන්ත්‍රීවරුන් අඩු වීම", "පනත් සම්මත කළ නොහැකි වීම", "මන්ත්‍රීවරුන්ට රජයේ යෝජනා පරාජය කළ හැකි වූ නමුත් ආණ්ඩුව පවත්වාගෙන යාමේ වගකීමක් ඔවුන්ට නොතිබිණි."),
    q(T, "ශ්‍රී ලංකාවට නව ආණ්ඩුක්‍රමයක් නිර්දේශ කිරීම සඳහා 1927 දී මෙරටට පැමිණි රාජකීය කොමිසම කුමක්ද?", "ඩොනමෝර් කොමිසම (Donoughmore Commission)", "කෝල්බෲක් කොමිසම", "සෝල්බරි කොමිසම", "කීල් කොමිසම", "අර්ල් ඩොනමෝර් සාමිවරයාගේ ප්‍රධානත්වයෙන් පැමිණි කොමිසම මෙරට දේශපාලන පක්ෂ, සංවිධාන හා ජනතාවගෙන් සාක්ෂි විමසීය."),
    q(T, "1931 දී ක්‍රියාත්මක කරන ලද ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් මෙරට ස්ථාපිත කරන ලද නව ව්‍යවස්ථාදායකය කුමක්ද?", "රාජ්‍ය මන්ත්‍රණ සභාව (State Council of Ceylon)", "පාර්ලිමේන්තුව", "ව්‍යවස්ථාදායක සභාව", "සෙනෙට් සභාව", "ව්‍යවස්ථාදායක සහ විධායක බලතල දෙකම ක්‍රියාත්මක කළ රාජ්‍ය මන්ත්‍රණ සභාව සාමාජිකයන් 61 දෙනෙකුගෙන් සමන්විත විය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් මෙරට ජනතාවට දායාද කරන ලද ශ්‍රේෂ්ඨතම ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකම කුමක්ද?", "සර්වජන ඡන්ද බලය (Universal Adult Suffrage - 1931)", "සීමිත ඡන්ද බලය", "ඉඩම් හිමියන්ට පමණක් ඡන්දය දීම", "පිරිමින්ට පමණක් ඡන්දය දීම", "වයස අවුරුදු 21 සම්පූර්ණ වූ ස්ත්‍රී පුරුෂ භේදයකින් හෝ දේපළ, අධ්‍යාපන සීමාවකින් තොරව සැමට ඡන්ද බලය ලැබුණු ආසියාවේ ප්‍රථම රට ලංකාවයි."),
    q(T, "1931 දී ශ්‍රී ලංකාවට සර්වජන ඡන්ද බලය ලබාදීමට ඩොනමෝර් කොමිසම හමුවේ දැඩිව පෙනී සිටි කම්කරු නායකයා කවුද?", "ඒ. ඊ. ගුණසිංහ (A. E. Goonesinha)", "ඩී. ඇස්. සේනානායක", "ඊ. ඩබ්ලිව්. පෙරේරා", "පොන්නම්බලම් රාමනාදන්", "සාමාන්‍ය කම්කරු හා ගොවි ජනතාවට ඡන්ද බලය ලබාදිය යුතු බවට ලංකා කම්කරු සංගමය වෙනුවෙන් ඒ. ඊ. ගුණසිංහ මහතා සාක්ෂි දුන්නේය."),
    q(T, "1931 සර්වජන ඡන්ද බලය යටතේ මෙරට ප්‍රථම වරට රාජ්‍ය මන්ත්‍රණ සභාවට තේරී පත් වූ ප්‍රථම මන්ත්‍රීවරිය (කාන්තා නියෝජිතවරිය) කවුද?", "ඇඩ්ලින් මොලමුරේ මහත්මිය (Lady Adeline Molamure)", "ෆ්ලොරන්ස් සේනානායක", "විවියන් ගුණවර්ධන", "සිරිමාවෝ බණ්ඩාරනායක", "රුවන්වැල්ල ආසනයෙන් තරඟ වැදී නිතරඟයෙන් තේරී පත් වූ ඇඩ්ලින් මොලමුරේ මහත්මිය ලංකාවේ ප්‍රථම කාන්තා පාර්ලිමේන්තු මන්ත්‍රීවරිය වූවාය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ අමාත්‍යාංශ කටයුතු පාලනය කිරීම සඳහා හඳුන්වා දුන් සුවිශේෂී ක්‍රමය කුමක්ද?", "විධායක කාරක සභා ක්‍රමය (Executive Committee System)", "කැබිනට් ආණ්ඩු ක්‍රමය", "ජනාධිපති ක්‍රමය", "ඒකමණ්ඩල ක්‍රමය", "රාජ්‍ය මන්ත්‍රණ සභාව විධායක කාරක සභා 7 කට බෙදා, එක් එක් කාරක සභාවේ සභාපතිවරයා අදාළ විෂය භාර ඇමතිවරයා බවට පත් විය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ විධායක කාරක සභා 7 ට අයත් වූ ප්‍රධාන විෂයයන් අතරට අයත් නොවන්නේ කුමක්ද?", "ආරක්ෂක සහ විදේශ කටයුතු", "ස්වදේශ කටයුතු සහ කෘෂිකර්මය", "අධ්‍යාපනය සහ සෞඛ්‍යය", "පළාත් පාලනය, සන්නිවේදනය හා කම්කරු", "ආරක්ෂක, විදේශ කටයුතු සහ මුදල් යන ප්‍රධාන විෂයයන් ආණ්ඩුකාරවරයා යටතේ පැවති නිලලත් රාජ්‍ය නිලධාරීන් තිදෙනා සතු විය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ ආණ්ඩුකාරවරයා විසින් පත්කරන ලද ප්‍රධාන බ්‍රිතාන්‍ය රාජ්‍ය නිලධාරීන් (Officers of State) තිදෙනා කවුරුන්ද?", "මහලේකම්, නීති ලේකම් සහ මුදල් ලේකම්", "අගමැති, කථානායක සහ විනිසුරු", "හමුදාපති, පොලිස්පති සහ දිසාපති", "අධ්‍යාපන ලේකම්, සෞඛ්‍ය ලේකම් සහ කෘෂිකර්ම ලේකම්", "මෙම නිලධාරීන් තිදෙනා රාජ්‍ය මන්ත්‍රණ සභාවේ වාඩිවී ඡන්දය නොමැතිව වැදගත් අමාත්‍යාංශ පාලනය කළහ."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමයේ කෘෂිකර්ම හා ඉඩම් අමාත්‍යවරයා ලෙස පත්වී රජරට වාරිමාර්ග හා ගොවිජනපද පුනරුදයක් ඇතිකළ නායකයා කවුද?", "ඩී. ඇස්. සේනානායක (D. S. Senanayake)", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ජෝන් කොතලාවල", "මින්නේරිය, පරාක්‍රම සමුද්‍රය, කන්තලේ ඇතුළු පැරණි වැව් ප්‍රතිසංස්කරණය කර වියළි කලාපයේ දැවැන්ත ගොවිජනපද ව්‍යාපාර බිහිකළේය."),
    q(T, "ඩී. ඇස්. සේනානායක මහතා විසින් 1935 දී ගොවීන්ට ඉඩම් කට්ටි ලබාදීම සඳහා සම්මත කළ ඓතිහාසික පනත කුමක්ද?", "1935 ඉඩම් සංවර්ධන ආඥා පනත (Land Development Ordinance)", "මුඩුබිම් පනත", "ධාන්‍ය බදු පනත", "කුරුඳු පනත", "ඉඩම් නැති ගැමි පවුල්වලට පරම්පරාගතව භුක්ති විඳිය හැකි පරිදි රජයේ ඉඩම් හා සහනාධාර ලබාදීමට මෙමගින් පියවර ගැනිණි."),
    q(T, "ඩොනමෝර් පාලන සමයේ අධ්‍යාපන අමාත්‍යවරයා ලෙස කටයුතු කරමින් 'නිදහස් අධ්‍යාපනයේ පියා' බවට පත්වූ නායකයා කවුද?", "ආචාර්ය සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර (Dr. C. W. W. Kannangara)", "ඩී. ඇස්. සේනානායක", "ඩී. බී. ජයතිලක", "ටී. බී. ජයා", "1945 දී පෙරපාසලේ සිට විශ්වවිද්‍යාලය දක්වා නොමිලේ අධ්‍යාපනය ලබාදීමේ ඓතිහාසික නිදහස් අධ්‍යාපන පනත කන්නන්ගර මහතා විසින් සම්මත කරවන ලදී."),
    q(T, "ග්‍රාමීය දක්ෂ දරුවන්ට උසස් ඉංග්‍රීසි හා විද්‍යා අධ්‍යාපනය ලබාදීම සඳහා සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර මහතා දිවයින පුරා ආරම්භ කළ පාසල් වර්ගය කුමක්ද?", "මධ්‍ය මහා විද්‍යාල (Central Colleges)", "පිරිවෙන්", "ජාත්‍යන්තර පාසල්", "මිෂනාරි පාසල්", "දිවයිනේ සෑම ආසනයකම නේවාසිකාගාර හා ශිෂ්‍යත්ව පහසුකම් සහිත මධ්‍ය විද්‍යාල 54 ක් ආරම්භ කරමින් ග්‍රාමීය දරුවන්ට නිදහස් අධ්‍යාපනයේ දොරටු විවර කළේය."),
    q(T, "ඩොනමෝර් යුගයේ සෞඛ්‍ය අමාත්‍යවරයා ලෙස කටයුතු කරමින් මැලේරියා රෝගය මර්දනය කිරීමට සහ නොමිලේ සෞඛ්‍ය සේවය සැලසීමට කටයුතු කළේ කවුද?", "ශ්‍රීමත් ජෝර්ජ් ඊ. ද සිල්වා (Sir George E. de Silva)", "ඩී. ඇස්. සේනානායක", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ජෝන් කොතලාවල", "DDT කෘමිනාශකය භාවිතයෙන් මැලේරියාව තුරන් කිරීමටත් දිවයින පුරා රජයේ රෝහල් ජාලය පුළුල් කිරීමටත් එතුමා මූලික විය."),
    q(T, "ක්‍රි.ව. 1935 දෙසැම්බර් 18 වන දින ශ්‍රී ලංකාවේ ප්‍රථම දේශපාලන පක්ෂය ලෙස ආරම්භ කරන ලද පක්ෂය කුමක්ද?", "ලංකා සමසමාජ පක්ෂය (Lanka Sama Samaja Party - LSSP)", "එක්සත් ජාතික පක්ෂය", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "ද්‍රවිඩ එක්සත් පෙරමුණ", "ආචාර්ය එන්. එම්. පෙරේරා, පිලිප් ගුණවර්ධන, ආචාර්ය කොල්වින් ආර්. ද සිල්වා ඇතුළු තරුණ වාමාංශිකයන් විසින් පූර්ණ ජාතික නිදහස හා සමාජවාදය අරමුණු කරගෙන පිහිටුවන ලදී."),
    q(T, "බ්‍රිතාන්‍ය පොපි මල් (Poppy Day) අලෙවියට විරෝධය පාමින් සමසමාජ නායකයන් විසින් දේශීය අරමුදල් පිහිටුවීමට ඇරඹූ ව්‍යාපාරය කුමක්ද?", "සූරිය මල් ව්‍යාපාරය (Suriya Mal Movement)", "නෙළුම් මල් ව්‍යාපාරය", "ඔලු මල් ව්‍යාපාරය", "රෝස මල් ව්‍යාපාරය", "පළමු ලෝක යුද්ධයේ බ්‍රිතාන්‍ය සෙබළුන්ට ආධාර එකතු කිරීමට විරුද්ධව දේශීය දුගී ජනතාවට සහ මැලේරියා රෝගීන්ට පිහිටවීමට සූරිය මල් අලෙවි කළහ."),
    q(T, "1934-1935 මහා මැලේරියා වසංගත සමයේදී කෑගල්ල හා රුවන්වැල්ල ප්‍රදේශවල ජනතාවට පරිප්පු බෙදමින් සේවය කළ සමසමාජ නායකයා ලැබූ අන්වර්ථ නාමය කුමක්ද?", "පරිප්පු මහත්තයා (ආචාර්ය එන්. එම්. පෙරේරා)", "සීනි මහත්තයා", "හාල් මහත්තයා", "තේ මහත්තයා", "ආචාර්ය එන්. එම්. පෙරේරා සහ සමසමාජ තරුණයන් ගම්බිම්වලට ගොස් බෙහෙත් හා ආහාර බෙදාදෙමින් කළ සේවය නිසා ජනතාව ආදරයෙන් එසේ හැඳින්වූහ."),
    q(T, "ක්‍රි.ව. 1944 දී ජී. ජී. පොන්නම්බලම් මහතා විසින් දෙමළ ජනතාවගේ දේශපාලන අයිතිවාසිකම් වෙනුවෙන් පිහිටුවූ පක්ෂය කුමක්ද?", "සමස්ත ලංකා දෙමළ කොංග්‍රසය (All Ceylon Tamil Congress - ACTC)", "ද්‍රවිඩ එක්සත් විමුක්ති පෙරමුණ", "ෆෙඩරල් පක්ෂය", "ලංකා ජාතික සංගමය", "ව්‍යවස්ථාදායකයේ සුළුතර ජාතීන්ට 50% ක් සහ බහුතරයට 50% ක් වශයෙන් 'පනහට පනහ' (Fifty-Fifty) ඉල්ලීම මෙම පක්ෂය විසින් ඉදිරිපත් කරන ලදී."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේදී මිත්‍ර හමුදාවන්ගේ 'ගිණිකොනදිග ආසියානු විධාන මූලස්ථානය' (SEAC) ස්ථාපිත කර තිබුණේ ලංකාවේ කොහේද?", "මහනුවර පේරාදෙණිය උද්භිද උද්‍යානයේ (ලෝඩ් මවුන්ට්බැටන්ගේ ප්‍රධානත්වයෙන්)", "කොළඹ කොටුවේ", "ත්‍රිකුණාමලයේ", "ගාල්ලේ", "ලෝඩ් ලුවී මවුන්ට්බැටන් ප්‍රමුඛ මිත්‍ර හමුදා සේනාධිනායකයන් ජපානයට එරෙහි ආසියානු යුද මෙහෙයුම් මෙහෙයවූයේ පේරාදෙණියේ සිටය."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේ 1942 අප්‍රේල් 5 වන දින පාස්කු ඉරිදා ජපාන ගුවන් හමුදාව විසින් බෝම්බ හෙළන ලද්දේ කුමන නගරයටද?", "කොළඹ නගරයට (Colombo Easter Sunday Raid)", "මහනුවරට", "යාපනයට", "අනුරාධපුරයට", "අද්මිරාල් චුයිචි නගුමෝගේ ප්‍රධානත්වයෙන් යුත් ජපන් ගුවන් යානා කොළඹ වරායට සහ රත්මලාන ගුවන් තොටුපළට දැවැන්ත බෝම්බ ප්‍රහාරයක් එල්ල කළේය."),
    q(T, "1942 අප්‍රේල් 9 වන දින ජපන් ගුවන් ප්‍රහාරවලට ලක්වූ ලංකාවේ නැගෙනහිර වරාය නගරය කුමක්ද?", "ත්‍රිකුණාමලය (Trincomalee)", "මඩකලපුව", "හම්බන්තොට", "පොතුවිල්", "ත්‍රිකුණාමල නාවික තටාකාංගනයට පහරදුන් ජපන් ගුවන් යානා මගින් බ්‍රිතාන්‍යයේ 'හර්මීස්' (HMS Hermes) ගුවන් යානා ප්‍රවාහන නෞකාව මඩකලපුව මුහුදේදී ගිල්වා දමන ලදී."),
    q(T, "දෙවන ලෝක යුද්ධය අවසන් අදියරට එළඹෙත්ම ලංකාවට පූර්ණ නිදහස ලබාගැනීම සඳහා ආණ්ඩුක්‍රමයක් සැකසීමට පත්කළ කොමිසම කුමක්ද?", "සෝල්බරි කොමිසම 1944 (Soulbury Commission)", "ඩොනමෝර් කොමිසම", "කෝල්බෲක් කොමිසම", "මැනිං කොමිසම", "හර්වල්ඩ් සෝල්බරි සාමිවරයාගේ ප්‍රධානත්වයෙන් යුත් කොමිසම ලංකාවට පැමිණ නව පාර්ලිමේන්තු ආණ්ඩුක්‍රමයක් නිර්දේශ කළේය."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රමය සැකසීම සඳහා ඩී. ඇස්. සේනානායක ප්‍රමුඛ ඇමති මණ්ඩලයට නීතිමය උපදෙස් දුන් සුප්‍රකට බ්‍රිතාන්‍ය ආණ්ඩුක්‍රම ව්‍යවස්ථා විශේෂඥයා කවුද?", "ශ්‍රීමත් අයිවර් ජෙනින්ග්ස් (Sir Ivor Jennings)", "ලෝඩ් සෝල්බරි", "ලෝඩ් මවුන්ට්බැටන්", "ජෝන් ඩොයිලි", "ලංකා විශ්වවිද්‍යාලයේ ප්‍රථම උපකුලපතිවරයා වූ ජෙනින්ග්ස් මහතා සෝල්බරි ව්‍යවස්ථාවේ මූලික කෙටුම්පත සකස් කිරීමට විශාල සහායක් දුන්නේය."),
    q(T, "1946 සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් මෙරට ස්ථාපිත කරන ලද ව්‍යවස්ථාදායකයේ සභා දෙක මොනවාද?", "නියෝජිත මන්ත්‍රී මණ්ඩලය සහ සෙනෙට් සභාව (ද්විමණ්ඩල පාර්ලිමේන්තුව)", "රාජ්‍ය මන්ත්‍රණ සභාව සහ විධායක සභාව", "ජාතික රාජ්‍ය සභාව සහ පාර්ලිමේන්තුව", "මහජන සභාව සහ සෙනෙට් සභාව", "ජනතා ඡන්දයෙන් තේරී පත්වන පහළ මන්ත්‍රී මණ්ඩලයක් (නියෝජිත මන්ත්‍රී මණ්ඩලය) සහ උගත් ප්‍රභූන්ගෙන් යුත් ඉහළ මන්ත්‍රී මණ්ඩලයක් (සෙනෙට් සභාව) පිහිටුවන ලදී."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රමයේ සුළුතර ආගමික හා වාර්ගික කොටස්වල අයිතිවාසිකම් ආරක්ෂා කිරීම සඳහා ඇතුළත් කළ විශේෂ වගන්තිය කුමක්ද?", "29 වන වගන්තිය (Section 29)", "10 වන වගන්තිය", "5 වන වගන්තිය", "50 වන වගන්තිය", "කිසිදු ආගමකට හෝ ජාතියකට අවාසි වන හෝ විශේෂ වරප්‍රසාද දෙන කිසිදු නීතියක් පාර්ලිමේන්තුවට සම්මත කළ නොහැකි බවට 29(2) වගන්තියෙන් ආරක්ෂාව සලසා තිබිණි."),
    q(T, "ක්‍රි.ව. 1946 සැප්තැම්බර් මස ලංකා ජාතික සංගමය, සිංහල මහා සභාව හා මුස්ලිම් ලීගය එක්ව ඩී. ඇස්. සේනානායකගේ ප්‍රධානත්වයෙන් පිහිටුවූ පක්ෂය කුමක්ද?", "එක්සත් ජාතික පක්ෂය (United National Party - UNP)", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "සමසමාජ පක්ෂය", "කොමියුනිස්ට් පක්ෂය", "සියලු ජාතීන් හා ප්‍රජාවන් නියෝජනය වන පරිදි එක්සත් ලංකාවක් ගොඩනැගීමේ අරමුණින් සේනානායක මැතිතුමා මෙම පක්ෂය පිහිටුවීය."),
    q(T, "1947 දී පැවති ප්‍රථම පාර්ලිමේන්තු මහ මැතිවරණයෙන් ජයග්‍රහණය කරමින් නිදහස් ශ්‍රී ලංකාවේ ප්‍රථම අග්‍රාමාත්‍යවරයා බවට පත් වූයේ කවුද?", "මහාමාන්‍ය ඩී. ඇස්. සේනානායක (D. S. Senanayake)", "ඩඩ්ලි සේනානායක", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ශ්‍රීමත් ජෝන් කොතලාවල", "1947 සැප්තැම්බර් 24 දින එතුමා අග්‍රාමාත්‍ය ධුරයේ දිවුරුම් දුන් අතර 'ජාතියේ පියා' (Father of the Nation) ලෙස ගෞරවයට පාත්‍ර විය."),
    q(T, "ශ්‍රී ලංකාවට බ්‍රිතාන්‍ය කිරීටයෙන් පූර්ණ ඩොමීනියන් නිදහස ලැබුණු ඓතිහාසික දිනය කුමක්ද?", "1948 පෙබරවාරි 4 වන දින (February 4, 1948)", "1947 සැප්තැම්බර් 24", "1972 මැයි 22", "1956 අප්‍රේල් 12", "වසර 133 ක බ්‍රිතාන්‍ය පාලනය සහ වසර 443 ක යුරෝපීය යටත්විජිත යුගය නිමාවට පත්කරමින් ශ්‍රී ලංකාව නිදහස් ස්වෛරී රාජ්‍යයක් බවට පත්විය."),
    q(T, "1948 පෙබරවාරි 4 නිදහස් උළෙලේදී කොළඹ ටොරින්ටන් චතුරශ්‍රයේ (නිදහස් චතුරශ්‍රයේ) නිදහස් පාර්ලිමේන්තුව විවෘත කළ බ්‍රිතාන්‍ය රජ පවුලේ නියෝජිතයා කවුද?", "ග්ලොස්ටර් ආදිපාදවරයා (Duke of Gloucester - හයවන ජෝර්ජ් රජු වෙනුවෙන්)", "මවුන්ට්බැටන් සාමි", "සෝල්බරි සාමි", "චාල්ස් කුමරු", "නිදහස් ප්‍රකාශනය සහ පාර්ලිමේන්තු පනත භාරදෙමින් ග්ලොස්ටර් ආදිපාදවරයා නිදහස් මන්දිරයේදී ප්‍රථම පාර්ලිමේන්තු සැසිවාරය විවෘත කළේය."),
    q(T, "නිදහස් ශ්‍රී ලංකාවේ ප්‍රථම අග්‍රණ්ඩුකාරවරයා (Governor-General) ලෙස පත් වූයේ කවුද?", "ශ්‍රීමත් හෙන්රි මන්ක්-මේසන් මුවර් (Sir Henry Monck-Mason Moore)", "සෝල්බරි සාමි", "ශ්‍රීමත් ඔලිවර් ගුණතිලක", "විලියම් ගොපල්ලව", "පසුව 1949 දී සෝල්බරි සාමිවරයා අග්‍රණ්ඩුකාර ධුරයට පත්විය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම ලාංකික අග්‍රණ්ඩුකාරවරයා ලෙස 1954 දී පත් වූ අසහාය රාජ්‍යතාන්ත්‍රිකයා කවුද?", "ශ්‍රීමත් ඔලිවර් ගුණතිලක (Sir Oliver Goonetilleke)", "විලියම් ගොපල්ලව", "ඩී. ඇස්. සේනානායක", "ජෝන් කොතලාවල", "දෙවන ලෝක යුද්ධ සමයේ සිවිල් ආරක්ෂක කොමසාරිස් ලෙසද නිදහස ලබාගැනීමේ සාකච්ඡාවලදීද ඔලිවර් ගුණතිලක මහතා විශිෂ්ට සේවයක් කළේය."),
    q(T, "1952 දී ගාලුමුවදොර පිටියේදී අශ්වයා පිටින් ඇදවැටී අභාවප්‍රාප්ත වූ නිදහස් ලංකාවේ ප්‍රථම අගමැතිවරයා කවුද?", "මහාමාන්‍ය ඩී. ඇස්. සේනානායක", "ඩඩ්ලි සේනානායක", "ජෝන් කොතලාවල", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "එතුමාගේ හදිසි අභාවයෙන් පසු එතුමාගේ පුත් ඩඩ්ලි සේනානායක මහතා මෙරට දෙවන අග්‍රාමාත්‍යවරයා ලෙස පත් විය."),
    q(T, "ශ්‍රී ලංකාවේ වියළි කලාපය සංවර්ධනය කිරීම සඳහා ඩී. ඇස්. සේනානායක මහතා විසින් ආරම්භ කළ දැවැන්තම බහුකාර්ය වාරි ව්‍යාපෘතිය කුමක්ද?", "ගල්ඔය සංවර්ධන ව්‍යාපාරය සහ සේනානායක සමුද්‍රය (ඉඟිනියාගල)", "මහවැලි ව්‍යාපාරය", "උඩවලව ව්‍යාපාරය", "කලා වැව", "දිගාමඩුල්ල ප්‍රදේශයේ ගල්ඔය හරස් කර සේනානායක සමුද්‍රය ඉදිකරමින් ගොවි පවුල් දහස් ගණනක් පදිංචි කරවන ලදී."),
    q(T, "ක්‍රි.ව. 1951 දී එක්සත් ජාතික පක්ෂයෙන් ඉවත්වී 'ශ්‍රී ලංකා නිදහස් පක්ෂය' (SLFP) ආරම්භ කළ නායකයා කවුද?", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක (S. W. R. D. Bandaranaike)", "ඩඩ්ලි සේනානායක", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "පිලිප් ගුණවර්ධන", "සඟ, වෙද, ගුරු, ගොවි, කම්කරු යන 'පංච මහා බලවේගය' පෙරටු කරගනිමින් මැද මාවතේ සමාජවාදී ප්‍රතිපත්තියක් සහිතව මෙම පක්ෂය පිහිටුවන ලදී."),
    q(T, "1956 මහ මැතිවරණයේදී මහජන එක්සත් පෙරමුණ (MEP) ජයග්‍රහණය කරවීම සඳහා පෙරට පැමිණි 'පංච මහා බලවේගය' කුමක්ද?", "සඟ, වෙද, ගුරු, ගොවි, කම්කරු", "රජු, ඇමති, හමුදාව, වෙළඳුන්, ගොවීන්", "තරුණ, වැඩිහිටි, ළමා, කාන්තා, සිසු", "වතුහිමියන්, නීතිඥයන්, දොස්තරවරුන්, ඉංජිනේරුවන්, මහාචාර්යවරුන්", "සාමාන්‍ය සිංහල බෞද්ධ ග්‍රාමීය බලවේග ඒකරාශී කරමින් බණ්ඩාරනායක මහතා 1956 දී ඓතිහාසික ජනතා ආණ්ඩුවක් පිහිටුවීය."),
    q(T, "1956 දී එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක රජය විසින් සම්මත කරන ලද මතභේදාත්මක ප්‍රධාන පනත කුමක්ද?", "රාජ්‍ය භාෂා පනත හෙවත් සිංහල පමණක් පනත (Official Language Act of 1956)", "නිදහස් අධ්‍යාපන පනත", "ඉඩම් පනත", "පුරවැසි පනත", "ඉංග්‍රීසි වෙනුවට සිංහල භාෂාව රාජ්‍ය භාෂාව බවට පත්කළ මෙම පනත නිසා පසුව ජාතික අර්බුදයක් නිර්මාණය විය."),
    q(T, "1956 රජය විසින් පොදු ජනතාවගේ ප්‍රවාහන හා ආර්ථික පහසුව සඳහා රජයට පවරා ගත් (ජනසතු කළ) ප්‍රධාන අංශ දෙක මොනවාද?", "බස් ප්‍රවාහන සේවය (CTB) සහ කොළඹ වරාය (Port Commission)", "දුම්රිය සහ ගුවන් සේවය", "තේ වතු සහ රබර් වතු", "පාසල් සහ රෝහල්", "පෞද්ගලික බස් කොම්පැනි ඒකාධිකාරය අවසන් කර ලංකා ගමනාගමන මණ්ඩලය (ලංගම) පිහිටුවා පොදු ප්‍රවාහනය ජනසතු කරන ලදී."),
    q(T, "බණ්ඩාරනායක රජය විසින් මෙරට රැඳී සිටි බ්‍රිතාන්‍ය හමුදා කඳවුරු ඉවත් කරමින් ස්වෛරීභාවය තහවුරු කළ ස්ථාන දෙක මොනවාද?", "කටුනායක ගුවන් හමුදා කඳවුර සහ ත්‍රිකුණාමල නාවික කඳවුර", "කොළඹ කොටුව සහ ගාලු කොටුව", "දියතලාව සහ පනාගොඩ", "මහනුවර සහ අනුරාධපුරය", "1957 දී බ්‍රිතාන්‍යයන් සතුවූ මෙම කඳවුරු නිල වශයෙන් ලංකා රජය යටතට පවරා ගන්නා ලදී."),
    q(T, "1959 සැප්තැම්බර් 25 වන දින අග්‍රාමාත්‍ය එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක මහතා ඝාතනයට ලක්වූයේ කාගේ වෙඩි ප්‍රහාරයෙන්ද?", "තල්දූවේ සෝමාරාම", "ඔස්මන් ද සිල්වා", "හෙන්රි පේද්‍රිස්", "එන්. එම්. පෙරේරා", "රොස්මිඩ් පෙදෙසේ තම නිවසේදී අගමැතිවරයාට වෙඩි තබන ලද අතර පසුදා (සැප්තැම්බර් 26) එතුමා කොළඹ මහ රෝහලේදී අභාවප්‍රාප්ත විය."),
    q(T, "ලොව ප්‍රථම අග්‍රාමාත්‍යවරිය (World's First Woman Prime Minister) ලෙස 1960 ජූලි මාසයේදී ඉතිහාසගත වූයේ කවුද?", "සිරිමාවෝ ආර්. ඩී. බණ්ඩාරනායක මැතිනිය (Sirimavo Bandaranaike)", "ඉන්දිරා ගාන්ධි", "මාග්‍රට් තැචර්", "ගෝල්ඩා මයර්", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක මහතාගේ අභාවයෙන් පසු ශ්‍රී ලංකා නිදහස් පක්ෂය මෙහෙයවමින් සිරිමාවෝ මැතිනිය ලෝකයේ ප්‍රථම අගමැතිවරිය ලෙස පත් වූවාය."),
    q(T, "1960 දී සිරිමාවෝ බණ්ඩාරනායක රජය විසින් සම්මත කරන ලද ඓතිහාසික අධ්‍යාපන පනත කුමක්ද?", "ආධාර ලබන පාසල් රජයට පවරා ගැනීමේ පනත (Assisted Schools Takeover Act)", "නිදහස් අධ්‍යාපන පනත", "විශ්වවිද්‍යාල පනත", "පිරිවෙන් පනත", "ආගමික මිෂනාරිවරුන් යටතේ පැවති පාසල් රජයට පවරා ගෙන ජාතික අධ්‍යාපන පද්ධතියක් ස්ථාපිත කරන ලදී."),
    q(T, "1964 දී සිරිමාවෝ බණ්ඩාරනායක සහ ඉන්දීය අගමැති ලාල් බහදූර් ශාස්ත්‍රි අතර අත්සන් කළ ගිවිසුම කුමක්ද?", "සිරිමා-ශාස්ත්‍රි ගිවිසුම (Sirima-Shastri Pact of 1964)", "ඉන්දු-ලංකා ගිවිසුම", "කච්චතිව් ගිවිසුම", "නොබැඳි ගිවිසුම", "ශ්‍රී ලංකාවේ විසූ වතුකරයේ ඉන්දීය සම්භවයක් ඇති ලක්ෂ 9 කට අධික ජනතාවගේ පුරවැසිභාවය පිළිබඳ ගැටලුව විසඳීමට රටවල් දෙක අතර පුරවැසිභාවය බෙදා දෙන ලදී."),
    q(T, "ක්‍රි.ව. 1974 දී ශ්‍රී ලංකාව සහ ඉන්දියාව අතර අත්සන් කළ ගිවිසුම මගින් ශ්‍රී ලංකාවට පූර්ණ අයිතිය තහවුරු වූ දූපත කුමක්ද?", "කච්චතිව් දූපත (Kachchatheevu Island)", "ඩෙල්ෆ්ට් දූපත", "නයිනතිව් දූපත", "මන්නාරම් දූපත", "සිරිමාවෝ බණ්ඩාරනායක සහ ඉන්දිරා ගාන්ධි අගමැතිනියන් අතර පැවති මිත්‍රශීලී සාකච්ඡා මගින් කච්චතිව් දූපතේ අයිතිය ශ්‍රී ලංකාවට හිමිවිය."),
    q(T, "1972 මැයි 22 වන දින සම්මත කරන ලද ප්‍රථම ජනරජ ආණ්ඩුක්‍රම ව්‍යවස්ථාව (First Republican Constitution) මගින් සිදුවූ ඓතිහාසික වෙනස කුමක්ද?", "බ්‍රිතාන්‍ය කිරීටයෙන් මුළුමනින්ම මිදී නිදහස්, ස්වෛරී, ස්වාධීන 'ශ්‍රී ලංකා ජනරජය' බිහිවීම", "නැවත රජෙකු පත්කිරීම", "සෙනෙට් සභාව ශක්තිමත් කිරීම", "විධායක ජනාධිපති ක්‍රමය ඇතිවීම", "බ්‍රිතාන්‍ය රැජින මෙරට රාජ්‍ය නායිකාව ලෙස පැවති තත්ත්වය අවසන් වී මෙරට ස්වදේශික ආණ්ඩුක්‍රම ව්‍යවස්ථාවක් බිහිවිය."),
    q(T, "1972 ප්‍රථම ජනරජ ආණ්ඩුක්‍රම ව්‍යවස්ථාව කෙටුම්පත් කළ ආණ්ඩුක්‍රම කටයුතු අමාත්‍යවරයා කවුද?", "ආචාර්ය කොල්වින් ආර්. ද සිල්වා (Dr. Colvin R. de Silva)", "ෆීලික්ස් ඩයස් බණ්ඩාරනායක", "එන්. එම්. පෙරේරා", "පීටර් කෙනමන්", "සමසමාජ නායකයෙකු හා ශ්‍රේෂ්ඨ ආණ්ඩුක්‍රම නීතිඥයෙකු වූ ආචාර්ය කොල්වින් ආර්. ද සිල්වාගේ ප්‍රධානත්වයෙන් නව ව්‍යවස්ථාව නිර්මාණය විය."),
    q(T, "1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ මෙරට පත් වූ ප්‍රථම ජනාධිපතිවරයා කවුද?", "විලියම් ගොපල්ලව මහතා (William Gopallawa)", "ජේ. ආර්. ජයවර්ධන", "ආර්. ප්‍රේමදාස", "ඩී. බී. විජේතුංග", "අවසාන අග්‍රණ්ඩුකාරවරයා වූ විලියම් ගොපල්ලව මහතා නාමමාත්‍රික රාජ්‍ය නායකයා ලෙස ප්‍රථම ජනාධිපති ධුරයට පත් විය."),
    q(T, "1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් ස්ථාපිත කරන ලද ඒකමණ්ඩල ව්‍යවස්ථාදායකය හැඳින්වූයේ කුමන නමින්ද?", "ජාතික රාජ්‍ය සභාව (National State Assembly)", "නියෝජිත මන්ත්‍රී මණ්ඩලය", "සෙනෙට් සභාව", "රාජ්‍ය මන්ත්‍රණ සභාව", "සෙනෙට් සභාව මුළුමනින්ම අහෝසි කර ජනතා පරමාධිපත්‍යය ක්‍රියාත්මක කරන උත්තරීතර ආයතනය ලෙස ජාතික රාජ්‍ය සභාව පිහිටුවන ලදී."),
    q(T, "1976 දී කොළඹදී පැවති 5 වන නොබැඳි ජාතීන්ගේ රාජ්‍ය නායක සමුළුවේ (Non-Aligned Summit) සභාපතිනිය ලෙස ලෝක නායකත්වය හෙබවූයේ කවුද?", "සිරිමාවෝ බණ්ඩාරනායක මැතිනිය", "ඉන්දිරා ගාන්ධි", "මාග්‍රට් තැචර්", "බෙනාසීර් භූතෝ", "රටවල් 86 ක රාජ්‍ය නායකයන් සහභාගී වූ මෙම සමුළුව මෙරට රාජ්‍යතාන්ත්‍රික ඉතිහාසයේ විශිෂ්ටතම ජාත්‍යන්තර ජයග්‍රහණයක් විය."),
    q(T, "ක්‍රි.ව. 1977 මහ මැතිවරණයෙන් අතිවිශිෂ්ට 5/6 ක බලයක් ලබාගෙන ආණ්ඩුවක් පිහිටුවූ නායකයා කවුද?", "ජේ. ආර්. ජයවර්ධන (J. R. Jayewardene)", "ආර්. ප්‍රේමදාස", "සිරිමාවෝ බණ්ඩාරනායක", "ඩඩ්ලි සේනානායක", "එක්සත් ජාතික පක්ෂය ආසන 168 න් 140 ක් දිනාගනිමින් ජේ. ආර්. ජයවර්ධන මහතාගේ නායකත්වයෙන් නව රජයක් පිහිටුවීය."),
    q(T, "1977 දී ජේ. ආර්. ජයවර්ධන රජය විසින් හඳුන්වා දුන් විප්ලවීය ආර්ථික ප්‍රතිපත්තිය කුමක්ද?", "විවෘත ආර්ථික ප්‍රතිපත්තිය (Open Economic Policy)", "සංවෘත ආර්ථිකය", "සමාජවාදී ආර්ථිකය", "ස්වයංපෝෂිත ආර්ථිකය", "ආනයන හා අපනයන පාලන ලිහිල් කරමින්, පෞද්ගලික අංශය හා විදේශ ආයෝජන දිරිගන්වන නිදහස් වෙළඳපොළ ආර්ථිකයක් මෙරට ස්ථාපිත කෙරිණි."),
    q(T, "1978 දී සම්මත කරන ලද දෙවන ජනරජ ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් මෙරටට හඳුන්වා දුන් ප්‍රධාන පාලන තන්ත්‍රය කුමක්ද?", "විධායක ජනාධිපති ක්‍රමය (Executive Presidential System)", "වෙස්ට්මිනිස්ටර් පාර්ලිමේන්තු ක්‍රමය", "සභාපති ක්‍රමය", "මිලිටරි පාලනය", "රාජ්‍ය නායකයා මෙන්ම ආණ්ඩුවේ ප්‍රධානියා සහ සේනාධිනායකයා වන ජනතා ඡන්දයෙන් තේරී පත්වන බලගතු විධායක ජනාධිපති ධුරයක් ස්ථාපිත කරන ලදී."),
    q(T, "1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ ශ්‍රී ලංකාවේ ප්‍රථම විධායක ජනාධිපතිවරයා බවට පත් වූයේ කවුද?", "ජේ. ආර්. ජයවර්ධන (J. R. Jayewardene)", "ආර්. ප්‍රේමදාස", "විලියම් ගොපල්ලව", "මහින්ද රාජපක්ෂ", "1978 පෙබරවාරි 4 වන දින ගාලුමුවදොර පිටියේදී ජේ. ආර්. ජයවර්ධන මහතා ප්‍රථම විධායක ජනාධිපතිවරයා ලෙස දිවුරුම් දුන්නේය."),
    q(T, "1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් පාර්ලිමේන්තු මැතිවරණ සඳහා හඳුන්වා දුන් නව ඡන්ද ක්‍රමය කුමක්ද?", "සමානුපාතික නියෝජන ඡන්ද ක්‍රමය (Proportional Representation System)", "කේවල ඡන්ද ක්‍රමය", "සීමිත ඡන්ද ක්‍රමය", "වාර්ගික ඡන්ද ක්‍රමය", "දේශපාලන පක්ෂ ලබාගන්නා ඡන්ද ප්‍රතිශතයට අනුකූලව මන්ත්‍රී ධුර බෙදී යන මනාප ඡන්ද ක්‍රමයක් හඳුන්වා දෙන ලදී."),
    q(T, "ශ්‍රී ලංකාවේ කෘෂිකර්මාන්තය හා විදුලිබල උත්පාදනය උදෙසා වසර 30 කින් නිම කිරීමට තිබූ මහවැලි සංවර්ධන ව්‍යාපෘතිය වසර 6 කින් නිමකළ දැවැන්ත වැඩසටහන කුමක්ද?", "කඩිනම් මහවැලි සංවර්ධන යෝජනා ක්‍රමය (Accelerated Mahaweli Scheme)", "ගල්ඔය ව්‍යාපාරය", "නිල්වලා ව්‍යාපාරය", "වලවේ ව්‍යාපාරය", "කොත්මලේ, වික්ටෝරියා, රන්දෙනිගල, රන්ටැඹේ සහ මාදුරුඔය ජලාශ ඉදිකරමින් රට සහලින් ස්වයංපෝෂිත කර විදුලිබල අවශ්‍යතාව සපුරාලන ලදී."),
    q(T, "කඩිනම් මහවැලි ව්‍යාපාරය මෙහෙයවූ ප්‍රකට කෘෂිකර්ම හා ඉඩම් සංවර්ධන අමාත්‍යවරයා කවුද?", "ගාමිණී දිසානායක (Gamini Dissanayake)", "ලලිත් ඇතුලත්මුදලි", "ආර්. ප්‍රේමදාස", "රොනී ද මැල්", "විදේශ ආධාර ලබාගනිමින් අති දැවැන්ත ජලාශ හා විදුලිබලාගාර කෙටි කලකින් නිමකිරීමට ගාමිණී දිසානායක මහතා නායකත්වය දුන්නේය."),
    q(T, "ශ්‍රී ලංකාවේ විශ්වවිද්‍යාල සිසුන්ට අධ්‍යාපනය කරගෙන යාම සඳහා 'මහපොළ ශිෂ්‍යත්ව අරමුදල' (Mahapola Higher Education Scholarship) ආරම්භ කළ අමාත්‍යවරයා කවුද?", "ලලිත් ඇතුලත්මුදලි (Lalith Athulathmudali)", "ගාමිණී දිසානායක", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "ආර්. ප්‍රේමදාස", "වෙළඳ අමාත්‍යවරයාව සිටියදී මහපොළ ලොතරැයිය හා වෙළඳ ප්‍රදර්ශන මගින් අරමුදල් රැස්කර අසරණ විශ්වවිද්‍යාල සිසුන්ට මාසික ශිෂ්‍යාධාර ලබාදීමේ ක්‍රමය ඇරඹීය."),
    q(T, "ශ්‍රී ලංකාවේ දිළිඳු ජනතාවගේ නිවාස ගැටලුව විසඳීම සඳහා 'ගම්උදාව' සහ 'දසලක්ෂය නිවාස සංවර්ධන වැඩසටහන' ක්‍රියාත්මක කළ ජනාධිපතිවරයා කවුද?", "රණසිංහ ප්‍රේමදාස (Ranasinghe Premadasa)", "ජේ. ආර්. ජයවර්ධන", "ඩී. බී. විජේතුංග", "චන්ද්‍රිකා බණ්ඩාරනායක", "ජනසවිය දිළිඳු සහන වැඩසටහන, ඇඟලුම් කම්හල් 200 වැඩසටහන හා ගම්උදාව මගින් ග්‍රාමීය ආර්ථිකය නගාසිටුවීමට ප්‍රේමදාස ජනාධිපතිවරයා කටයුතු කළේය."),
    q(T, "ශ්‍රී ලංකාවේ නිදහසින් පසු දේශපාලන හා ව්‍යවස්ථාමය ඉතිහාසයේ ප්‍රධානතම ජයග්‍රහණයක් ලෙස සැලකෙන්නේ කුමක්ද?", "ආසියාවේ පැරණිතම ප්‍රජාතන්ත්‍රවාදී සම්ප්‍රදාය රකිමින් අඛණ්ඩව ජනතා ඡන්දයෙන් ආණ්ඩු මාරු කිරීමේ නිදහස පැවතීම", "මිලිටරි පාලනයක් ඇතිවීම", "ආණ්ඩුක්‍රම අහෝසි වීම", "විදේශ ආධිපත්‍යයට යටත් වීම", "1931 සර්වජන ඡන්දයේ සිට අද දක්වාම ජනතාවගේ ඡන්ද බලයෙන් සාමකාමීව පාලකයන් තෝරාපත් කරගැනීමේ ශක්තිමත් ප්‍රජාතන්ත්‍රවාදී උරුමයක් ශ්‍රී ලංකාව සතුය."),
    q(T, "1910 මැකලම් ආණ්ඩුක්‍රමය යටතේ ව්‍යවස්ථාදායක සභාවට ඇතුළත් කළ නිලනොලත් තේරී පත්වන මන්ත්‍රී සංඛ්‍යාව කීයද?", "මන්ත්‍රීවරු 4 දෙනෙකි", "මන්ත්‍රීවරු 10 කි", "මන්ත්‍රීවරු 15 කි", "මන්ත්‍රීවරු 20 කි", "යුරෝපීය නාගරික 1, යුරෝපීය ග්‍රාමීය 1, බර්ගර් 1 සහ උගත් ලාංකික 1 වශයෙන් මුල්වරට තේරී පත්වන ආසන 4 ක් ඇති කෙරිණි."),
    q(T, "1911 දී උගත් ලාංකික ආසනය සඳහා ඡන්දය ප්‍රකාශ කිරීමට සුදුසුකම් ලැබූ මුළු ලාංකික ඡන්දදායකයන් සංඛ්‍යාව කොපමණද?", "2,934 දෙනෙකු පමණි", "ලක්ෂයක්", "පනස් දහසක්", "දස ලක්ෂයක්", "ඉංග්‍රීසි අධ්‍යාපනය සහ ඉහළ වාර්ෂික ආදායම/දේපළ තිබිය යුතු වූ බැවින් ඡන්ද අයිතිය හිමිවූයේ ජනගහනයෙන් 0.1% කටත් වඩා අඩු පිරිසකටය."),
    q(T, "1920 මැනිං ආණ්ඩුක්‍රමය යටතේ ව්‍යවස්ථාදායක සභාවේ මුළු මන්ත්‍රී සංඛ්‍යාව කීයක් දක්වා වැඩි කළේද?", "37 දෙනෙකු දක්වා (නිලලත් 14 සහ නිලනොලත් 23)", "15 ක් දක්වා", "50 ක් දක්වා", "100 ක් දක්වා", "ප්‍රථම වරට නිලනොලත් සාමාජිකයන් සංඛ්‍යාව නිලලත් සංඛ්‍යාවට වඩා වැඩි වූ නමුත් ආණ්ඩුකාරවරයාට නිෂේධ බලය පැවතිණි."),
    q(T, "1924 මැනිං-ඩෙවොන්ෂයර් ආණ්ඩුක්‍රමය යටතේ ව්‍යවස්ථාදායක සභාවේ මුළු සාමාජික සංඛ්‍යාව කීයද?", "49 කි (නිලනොලත් 34, නිලලත් 12, නම් කළ 3)", "20 කි", "30 කි", "60 කි", "නිලනොලත් මන්ත්‍රීවරුන්ට පැහැදිලි බහුතරයක් හිමිවූ අතර ප්‍රාදේශීය ආසන 23 ක් ඇතුළත් විය."),
    q(T, "1927 දී ලංකාවට පැමිණි ඩොනමෝර් කොමිසම නියෝජනය කළ සාමාජිකයන් සිව්දෙනා කවුරුන්ද?", "ඩොනමෝර් සාමි, ශ්‍රීමත් මැතිව් නේතන්, ශ්‍රීමත් ජෙෆ්රි බට්ලර් සහ ආචාර්ය ඩ්‍රමන්ඩ් ෂීල්ස්", "කෝල්බෲක්, කැමරන්, සෝල්බරි, මැනිං", "මැකලම්, බ්‍රවුන්රිග්, නෝර්ත්, ඩොයිලි", "මවුන්ට්බැටන්, ජෙනින්ග්ස්, සෝල්බරි, ක්ලීව්ලන්ඩ්", "මෙම සිව්පුද්ගල කොමිසම දිවයින පුරා සංචාරය කරමින් සාක්ෂි විමසා නව ආණ්ඩුක්‍රම වාර්තාව සකස් කළහ."),
    q(T, "ඩොනමෝර් කොමිසම විසින් මෙරට ව්‍යවස්ථාවෙන් සම්පූර්ණයෙන්ම අහෝසි කිරීමට නිර්දේශ කළ ක්‍රමය කුමක්ද?", "වාර්ගික නියෝජන ක්‍රමය (Communal Representation)", "ප්‍රාදේශීය නියෝජනය", "ඡන්ද ක්‍රමය", "අධිකරණය", "වාර්ගික නියෝජනය ජාතීන් අතර භේද වර්ධනය කරන පිළිකාවක් බව පෙන්වා දෙමින් එය මුළුමනින්ම අහෝසි කිරීමට කොමිසම නිර්දේශ කළේය."),
    q(T, "1931 ඩොනමෝර් රාජ්‍ය මන්ත්‍රණ සභාවේ මුළු මන්ත්‍රී ආසන 61 බෙදී තිබුණේ කෙසේද?", "ප්‍රාදේශීයව තේරී පත්වන 50, ආණ්ඩුකාරවරයා නම් කරන 8 සහ රාජ්‍ය නිලධාරීන් 3", "සියල්ල තේරී පත්වන 61", "තේරී පත්වන 30 සහ නම් කරන 31", "වාර්ගිකව තේරී පත්වන 61", "දිවයින මැතිවරණ කොට්ඨාස 50 කට බෙදා සර්වජන ඡන්දයෙන් මන්ත්‍රීවරු 50 ක් තෝරා පත් කරගන්නා ලදී."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමයේ විධායක කාරක සභා ක්‍රමයේදී පළාත් පාලන අමාත්‍යවරයා ලෙස කටයුතු කළේ කවුද?", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක මහතා", "ඩී. ඇස්. සේනානායක", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "ජෝන් කොතලාවල", "පළාත් පාලන විෂය භාරව කටයුතු කරමින් ගම්සභා හා නගර සභා බලගැන්වීමට බණ්ඩාරනායක මහතා පියවර ගත්තේය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමයේ කම්කරු, කර්මාන්ත හා වාණිජ අමාත්‍යවරයා ලෙස පත් වූ ප්‍රමුඛ නායකයා කවුද?", "පෙරී සුන්දරම් (Peri Sundaram) සහ පසුව සී. සුන්දරලිංගම්", "ඒ. ඊ. ගුණසිංහ", "එන්. එම්. පෙරේරා", "පිලිප් ගුණවර්ධන", "වතු කම්කරු නියෝජිතයෙකු වූ පෙරී සුන්දරම් මහතා මෙරට කම්කරු නීති සම්පාදනයට මූලික විය."),
    q(T, "ඩොනමෝර් පාලන සමයේ සන්නිවේදන හා රජයේ වැඩ පිළිබඳ අමාත්‍යවරයා ලෙස කටයුතු කළේ කවුද?", "ශ්‍රීමත් ජෝන් කොතලාවල (Sir John Kotelawala)", "ඩී. ඇස්. සේනානායක", "ඩී. බී. ජයතිලක", "ඊ. ඩබ්ලිව්. පෙරේරා", "මහා මාර්ග, ගුවන් තොටුපළවල් සහ වරාය පහසුකම් දියුණු කිරීමට කොතලාවල මහතා මූලික විය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමයේ ස්වදේශ කටයුතු අමාත්‍යවරයා මෙන්ම ඇමති මණ්ඩලයේ ප්‍රධානියා (Leader of the State Council) වූයේ කවුද?", "ශ්‍රීමත් ඩී. බී. ජයතිලක (Sir D. B. Jayatilaka)", "ඩී. ඇස්. සේනානායක", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "ජේම්ස් පීරිස්", "රාජ්‍ය මන්ත්‍රණ සභාවේ සභානායකවරයා ලෙස ශ්‍රීමත් ඩී. බී. ජයතිලක මහතා දීර්ඝ කාලයක් විශිෂ්ට සේවයක් ඉටු කළේය."),
    q(T, "ක්‍රි.ව. 1936 රාජ්‍ය මන්ත්‍රණ සභා මැතිවරණයෙන් පසු ඩී. ඇස්. සේනානායකගේ උපක්‍රමශීලී සැලසුමකට අනුව බිහිකළ අමාත්‍ය මණ්ඩලය හැඳින්වූයේ කුමක් ලෙසද?", "පිරිසිදු සිංහල ඇමති මණ්ඩලය (Pan-Sinhala Ministry)", "සභාග ඇමති මණ්ඩලය", "ජාතික ඇමති මණ්ඩලය", "සුළුතර ඇමති මණ්ඩලය", "විධායක කාරක සභා ක්‍රමයේ දුර්වලතා බ්‍රිතාන්‍ය රජයට ඔප්පු කර සම්පූර්ණ කැබිනට් ආණ්ඩුක්‍රමයක් දිනාගැනීමේ අරමුණින් මෙම පියවර ගත්තේය."),
    q(T, "ශ්‍රී ලංකාවේ දේශීය ව්‍යාපාරිකයන්ට හා කර්මාන්තකරුවන්ට ණය පහසුකම් ලබාදීම සඳහා 1939 දී පිහිටුවන ලද ප්‍රථම රාජ්‍ය වාණිජ බැංකුව කුමක්ද?", "ලංකා බැංකුව (Bank of Ceylon - 1939)", "මහජන බැංකුව", "ජාතික ඉතිරි කිරීමේ බැංකුව", "මහ බැංකුව", "ඩොනමෝර් රාජ්‍ය මන්ත්‍රණ සභාවේ වෙළඳ අමාත්‍යංශයේ මැදිහත්වීමෙන් දේශීය වෙළඳාම නගාසිටුවීමට ලංකා බැංකුව පිහිටුවන ලදී."),
    q(T, "1943 දී සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර මහතා විසින් රාජ්‍ය මන්ත්‍රණ සභාවට ඉදිරිපත් කළ ඓතිහාසික අධ්‍යාපන වාර්තාව කුමක්ද?", "කන්නන්ගර අධ්‍යාපන ප්‍රතිසංස්කරණ වාර්තාව (Kannangara Report)", "කෝල්බෲක් වාර්තාව", "සෝල්බරි වාර්තාව", "ඩොනමෝර් වාර්තාව", "නිදහස් අධ්‍යාපනය, මව්බසින් ඉගැන්වීම, මධ්‍ය විද්‍යාල පිහිටුවීම සහ ආගමික අධ්‍යාපනය අනිවාර්ය කිරීම මෙම වාර්තාවේ මූලික නිර්දේශ විය."),
    q(T, "නිදහස් අධ්‍යාපන පනත් කෙටුම්පත රාජ්‍ය මන්ත්‍රණ සභාවේදී විවාදයට ගත් අවස්ථාවේ කන්නන්ගර මහතාට සහාය පළකළ සුප්‍රකට මුස්ලිම් නායකයා කවුද?", "ආචාර්ය ටී. බී. ජයා (Dr. T. B. Jayah)", "සිද්ධි ලෙබ්බේ", "වාප්චි මරික්කාර්", "රාසික් ෆරීඩ්", "මුස්ලිම් ප්‍රජාව වෙනුවෙන් පූර්ණ සහයෝගය පළකරමින් නිදහස් අධ්‍යාපනය මෙරට දුප්පත් දරුවන්ගේ අයිතියක් බව ආචාර්ය ජයා මහතා ප්‍රකාශ කළේය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම පූර්ණ විශ්වවිද්‍යාලය ලෙස 1942 ජූලි 1 වන දින පිහිටුවන ලද ආයතනය කුමක්ද?", "ලංකා විශ්වවිද්‍යාලය (University of Ceylon - කොළඹ හා පේරාදෙණිය)", "විද්‍යෝදය සරසවිය", "විද්‍යාලංකාර සරසවිය", "මොරටුව සරසවිය", "කොළඹ වෛද්‍ය විද්‍යාලය හා යුනිවර්සිටි කොලීජිය ඒකාබද්ධ කර ශ්‍රීමත් අයිවර් ජෙනින්ග්ස්ගේ උපකුලපතිත්වයෙන් ලංකා විශ්වවිද්‍යාලය පිහිටුවන ලදී."),
    q(T, "1942 දෙවන ලෝක යුද්ධ සමයේදී කොකෝස් දූපතේදී (Cocos Islands) බ්‍රිතාන්‍ය පාලනයට එරෙහිව කැරලි ගැසූ ලාංකික සෙබළුන්ගේ නායකයා කවුද?", "බෝම්බියර් ග්‍රේෂන් ප්‍රනාන්දු (Bombardier Gratien Fernando)", "හෙන්රි පේද්‍රිස්", "පුරන් අප්පු", "කැප්පෙටිපොළ", "බ්‍රිතාන්‍ය අධිරාජ්‍යවාදීන්ට එරෙහිව කොකෝස් දූපතේ කාලතුවක්කු බලකායේ ලාංකික සෙබළුන් කැරලි ගැසූ අතර පසුව ග්‍රේෂන් ප්‍රනාන්දු එල්ලා මරා දමන ලදී."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේදී ලංකාවේ අත්‍යවශ්‍ය ආහාර ද්‍රව්‍ය බෙදාහැරීම සඳහා ස්ථාපිත කරන ලද ක්‍රමවේදය කුමක්ද?", "සලාක ක්‍රමය (Rationing System) සහ සමුපකාර සමිති ජාලය (Cooperative Stores)", "විවෘත වෙළඳාම", "මිල පාලනය අත්හැරීම", "අපනයනය වැඩි කිරීම", "හාල්, පිටි, සීනි සහ රෙදිපිළි පාලන මිලට සලාක පොත් මගින් බෙදාහැරීමට සමුපකාර ව්‍යාපාරය දිවයින පුරා ව්‍යාප්ත කෙරිණි."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේදී ලංකාවේ ඇතිවූ රබර් ඉල්ලුම සපුරාලීම සඳහා රබර් ගස්වලින් අධික ලෙස කිරි කැපීමේ ක්‍රමය හැඳින්වූයේ කුමක් ලෙසද?", "ස්ලෝටර් ටැපිං (Slaughter Tapping)", "සාමාන්‍ය කැපිල්ල", "විද්‍යාත්මක කැපිල්ල", "නව කිරි කැපිල්ල", "මිත්‍ර හමුදාවන්ට ටයර් සහ යුද උපකරණ සඳහා රබර් අත්‍යවශ්‍ය වූ බැවින් ගස විනාශ වන තරමට දිනපතා කිරි කැපීමට සිදුවිය."),
    q(T, "1940 දී ලංකා සමසමාජ පක්ෂයේ නායකයන් වූ එන්. එම්. පෙරේරා, පිලිප් ගුණවර්ධන සහ කොල්වින් ආර්. ද සිල්වා බ්‍රිතාන්‍යයන් විසින් සිරගත කළේ ඇයි?", "දෙවන ලෝක යුද්ධය අධිරාජ්‍යවාදී යුද්ධයක් බව පවසමින් ඊට විරුද්ධ වීම සහ වරාය කම්කරුවන් වර්ජනයට පෙළඹවීම නිසා", "හොරකම් කළ නිසා", "කැරලි ගැසූ නිසා", "බදු නොගෙවූ නිසා", "සිරගත කළ සමසමාජ නායකයන් 1942 දී බෝගම්බර සිරගෙදරින් රහසින් පලාගොස් ඉන්දියාවට ගොස් ඉන්දීය නිදහස් සටනට එක්වූහ."),
    q(T, "ක්‍රි.ව. 1944 දී ලංකාවේ ඇමති මණ්ඩලය විසින් සකස් කර බ්‍රිතාන්‍ය රජයට ඉදිරිපත් කළ නව ආණ්ඩුක්‍රම කෙටුම්පත හැඳින්වූයේ කුමන නමින්ද?", "ඇමතිවරුන්ගේ කෙටුම්පත (Ministers' Draft Constitution)", "සෝල්බරි කෙටුම්පත", "ඩොනමෝර් කෙටුම්පත", "ජෙනින්ග්ස් කෙටුම්පත", "ඩී. ඇස්. සේනානායකගේ නායකත්වයෙන් යුත් ඇමති මණ්ඩලය බ්‍රිතාන්‍යයට ඉදිරිපත් කළ මෙම කෙටුම්පත සෝල්බරි ව්‍යවස්ථාවේ පදනම විය."),
    q(T, "1944 දී සෝල්බරි කොමිසමේ සභාපතිවරයා වූ හර්වල්ඩ් සෝල්බරි සාමිවරයා සමග පැමිණි අනෙක් සාමාජිකයන් දෙදෙනා කවුරුන්ද?", "ශ්‍රීමත් ෆ්‍රෙඩ්රික් රීස් සහ ශ්‍රීමත් ෆ්‍රෙඩ්රික් බරෝස්", "මැතිව් නේතන් සහ ඩ්‍රමන්ඩ් ෂීල්ස්", "කෝල්බෲක් සහ කැමරන්", "මැනිං සහ ඩෙවොන්ෂයර්", "මෙම ත්‍රිපුද්ගල කොමිසම ලංකාවේ විවිධ දේශපාලන පක්ෂ හා ජන කණ්ඩායම් හමුවී සාකච්ඡා කළහ."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රමය යටතේ නියෝජිත මන්ත්‍රී මණ්ඩලයට (House of Representatives) තෝරාපත් කරගත් මුළු මන්ත්‍රී සංඛ්‍යාව කීයද?", "101 කි (ඡන්දයෙන් 95 ක් සහ ආණ්ඩුකාරවරයා නම් කළ 6 ක්)", "61 කි", "50 කි", "150 කි", "දිවයින මැතිවරණ කොට්ඨාස 89 කට බෙදා මන්ත්‍රීවරු 95 ක් ඡන්දයෙන් පත් කරගන්නා ලදී (බහු-මන්ත්‍රී ආසන ඇතුළුව)."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රමයේ ඉහළ මන්ත්‍රී මණ්ඩලය වූ සෙනෙට් සභාවේ (Senate) මුළු සාමාජික සංඛ්‍යාව කීයද?", "30 කි (නියෝජිත මන්ත්‍රී මණ්ඩලයෙන් 15 ක් සහ අග්‍රණ්ඩුකාරවරයා නම් කළ 15 ක්)", "50 කි", "20 කි", "10 කි", "වසර 6 ක කාලයක් සඳහා පත්වූ සෙනෙට් සභිකයන්ගෙන් තුනෙන් එකක් සෑම වසර දෙකකට වරක් විශ්‍රාම ගියහ."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ මෙරට විධායක බලය ක්‍රියාත්මක වූ ආකාරය කුමක්ද?", "අග්‍රාමාත්‍යවරයා ප්‍රමුඛ කැබිනට් මණ්ඩලය මගින් (අග්‍රණ්ඩුකාරවරයා නාමමාත්‍රික නායකයා විය)", "විධායක ජනාධිපති මගින්", "විධායක කාරක සභා මගින්", "ආණ්ඩුකාරවරයා තනිවම", "බ්‍රිතාන්‍ය වෙස්ට්මිනිස්ටර් පාර්ලිමේන්තු ක්‍රමය අනුව අගමැති ප්‍රමුඛ අමාත්‍ය මණ්ඩලය පාර්ලිමේන්තුවට වගකිව යුතු විය."),
    q(T, "1947 ප්‍රථම පාර්ලිමේන්තු මැතිවරණයේදී එක්සත් ජාතික පක්ෂය ආසන කීයක් දිනාගනිමින් විශාලතම පක්ෂය බවට පත්වූයේද?", "ආසන 42 ක් (ස්වාධීන මන්ත්‍රීවරුන්ගේ සහායෙන් රජයක් පිහිටුවීය)", "ආසන 80 ක්", "ආසන 95 ක්", "ආසන 20 ක්", "කිසිදු පක්ෂයකට තනි බහුතරයක් නොලැබුණු අතර ඩී. ඇස්. සේනානායක මහතා දෙමළ කොංග්‍රසය හා ස්වාධීන මන්ත්‍රීවරුන් සමග එක්ව රජය පිහිටුවීය."),
    q(T, "1947 දී ලංකා පාර්ලිමේන්තුවේ ප්‍රථම විපක්ෂ නායකවරයා ලෙස පත් වූයේ කවුද?", "ආචාර්ය එන්. එම්. පෙරේරා (LSSP නායක)", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ජී. ජී. පොන්නම්බලම්", "පීටර් කෙනමන්", "ආසන 10 ක් දිනාගත් ලංකා සමසමාජ පක්ෂයේ නායක ආචාර්ය එන්. එම්. පෙරේරා නිල විපක්ෂ නායක ධුරයට පත් විය."),
    q(T, "1947 දී ශ්‍රී ලංකා පාර්ලිමේන්තුවේ ප්‍රථම කථානායකවරයා (Speaker) ලෙස තේරී පත් වූයේ කවුද?", "ශ්‍රීමත් ඇල්ෆ්‍රඩ් ෆ්‍රැන්සිස් මොලමුරේ (Sir A. F. Molamure)", "සී. ඩබ්ලිව්. ඩබ්ලිව්. කන්නන්ගර", "එච්. එස්. ඉස්මයිල්", "විලියම් ගොපල්ලව", "මොලමුරේ මහතා රාජ්‍ය මන්ත්‍රණ සභාවේද ප්‍රථම කථානායකවරයා ලෙස සේවය කර තිබිණි."),
    q(T, "1947 දී බ්‍රිතාන්‍ය පාර්ලිමේන්තුව විසින් ලංකාවට පූර්ණ නිදහස ලබාදෙමින් සම්මත කළ ඓතිහාසික පනත කුමක්ද?", "1947 ලංකා නිදහස් පනත (Ceylon Independence Act 1947)", "කෝල්බෲක් පනත", "සෝල්බරි පනත", "ඩොනමෝර් පනත", "මෙම පනත මගින් ලංකාව සම්බන්ධයෙන් බ්‍රිතාන්‍ය පාර්ලිමේන්තුව සතුවූ සියලු ව්‍යවස්ථාදායක හා පාලන බලතල මුළුමනින්ම අහෝසි විය."),
    q(T, "1948 පෙබරවාරි 4 වන දින නිදහස ලැබීමෙන් පසු ශ්‍රී ලංකාවේ මුදල් පද්ධතිය ස්වාධීනව පාලනය කිරීම සඳහා 1950 දී පිහිටුවූ ආයතනය කුමක්ද?", "ශ්‍රී ලංකා මහ බැංකුව (Central Bank of Sri Lanka)", "ලංකා බැංකුව", "මහජන බැංකුව", "භාණ්ඩාගාරය", "ඇමරිකානු ආර්ථික විද්‍යාඥ ජෝන් එක්ස්ටර්ගේ (John Exter) වාර්තාව අනුව 1949 මුදල් නීති පනත යටතේ 1950 දී මහ බැංකුව පිහිටුවන ලදී."),
    q(T, "ශ්‍රී ලංකා මහ බැංකුවේ ප්‍රථම අධිපතිවරයා (Governor of the Central Bank) ලෙස පත් වූයේ කවුද?", "ජෝන් එක්ස්ටර් (John Exter)", "එන්. යූ. ජයවර්ධන", "ආතර් රණසිංහ", "ඉන්ද්‍රජිත් කුමාරස්වාමි", "ඇමරිකානු ෆෙඩරල් බැංකුවේ විශේෂඥයෙකු වූ ජෝන් එක්ස්ටර් මහතා මෙරට මහ බැංකුවේ ප්‍රථම අධිපතිවරයා ලෙස සේවය කළේය."),
    q(T, "ශ්‍රී ලංකා මහ බැංකුවේ ප්‍රථම ලාංකික අධිපතිවරයා ලෙස 1953 දී පත් වූයේ කවුද?", "එන්. යූ. ජයවර්ධන මහතා (N. U. Jayawardena)", "ජෝන් එක්ස්ටර්", "ආතර් රණසිංහ", "ගාමිණී කොරයා", "දක්ෂ ආර්ථික විද්‍යාඥයෙකු වූ එන්. යූ. ජයවර්ධන මහතා මෙරට ප්‍රථම ස්වදේශික මහ බැංකු අධිපතිවරයා විය."),
    q(T, "1952 දී ශ්‍රී ලංකාව සහ චීනය අතර අත්සන් කරන ලද ඓතිහාසික වෙළඳ ගිවිසුම කුමක්ද?", "රබර්-සහල් ගිවිසුම (Rubber-Rice Pact of 1952)", "තේ-තිරිඟු ගිවිසුම", "පොල්-සීනි ගිවිසුම", "නොබැඳි ගිවිසුම", "ශ්‍රී ලංකාවේ රබර් චීනයට ලබාදෙමින් චීනයෙන් සහල් මෙරටට ලබාගැනීමේ මෙම ගිවිසුම සීතල යුද්ධ සමයේ අත්සන් කළ විශිෂ්ට වෙළඳ සම්මුතියකි."),
    q(T, "1952 රබර්-සහල් ගිවිසුම අත්සන් කිරීමට බීජිං නුවරට ගිය ලංකාවේ වෙළඳ අමාත්‍යවරයා කවුද?", "ආර්. ජී. සේනානායක මහතා (R. G. Senanayake)", "ඩඩ්ලි සේනානායක", "ජෝන් කොතලාවල", "ජේ. ආර්. ජයවර්ධන", "ඇමරිකානු විරෝධය නොතකා ජාතික අවශ්‍යතාව වෙනුවෙන් ආර්. ජී. සේනානායක මහතා චීනය සමග මෙම ගිවිසුමට අත්සන් තැබීය."),
    q(T, "1953 අගෝස්තු 12 වන දින මෙරට ඉතිහාසයේ ප්‍රථම මහා 'හර්තාලය' (Hartal of 1953) ඇතිවීමට බලපෑ ආසන්න හේතුව කුමක්ද?", "හාල් සේරුවේ මිල ශත 25 සිට ශත 70 දක්වා ඉහළ දැමීම සහ සහනාධාර කප්පාදු කිරීම", "බස් ගාස්තු වැඩිවීම", "වැටුප් අඩුකිරීම", "විභාග ගාස්තු", "හාල් සහනාධාරය කප්පාදු කිරීමට විරෝධය පාමින් වෘත්තීය සමිති හා වාමාංශික පක්ෂ විසින් මුළු දිවයිනම අඩපණ කළ මහා හර්තාලය මෙහෙයවූහ."),
    q(T, "1953 හර්තාලය හේතුවෙන් දැඩි කම්පනයට පත්ව අග්‍රාමාත්‍ය ධුරයෙන් ඉල්ලා අස්වූ නායකයා කවුද?", "ඩඩ්ලි සේනානායක මහතා", "ජෝන් කොතලාවල", "ඩී. ඇස්. සේනානායක", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ඩඩ්ලි සේනානායක මහතා ඉල්ලා අස්වීමෙන් පසු ශ්‍රීමත් ජෝන් කොතලාවල මහතා අග්‍රාමාත්‍ය ධුරයට පත් විය."),
    q(T, "1955 දී ඉන්දුනීසියාවේ පැවති 'බැන්ඩුං සමුළුවට' (Bandung Conference) සහභාගී වී නොබැඳි විදේශ ප්‍රතිපත්තියට පදනම දැමූ ලංකාවේ අගමැතිවරයා කවුද?", "ශ්‍රීමත් ජෝන් කොතලාවල (Sir John Kotelawala)", "ඩඩ්ලි සේනානායක", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක", "ඩී. ඇස්. සේනානායක", "ආසියානු සහ අප්‍රිකානු රටවල් 29 ක නායකයන් සහභාගී වූ මෙම සමුළුවේදී යටත්විජිත විරෝධය සහ සාමකාමී සහජීවනය ප්‍රකාශයට පත් විය."),
    q(T, "1955 දෙසැම්බර් 14 වන දින ශ්‍රී ලංකාවට හිමිවූ ඓතිහාසික ජාත්‍යන්තර සාමාජිකත්වය කුමක්ද?", "එක්සත් ජාතීන්ගේ සංවිධානයේ (UN) පූර්ණ සාමාජිකත්වය ලැබීම", "පොදුරාජ්‍ය මණ්ඩල සාමාජිකත්වය", "සාර්ක් සාමාජිකත්වය", "යුරෝපා සංගම් සාමාජිකත්වය", "වසර ගණනාවක රාජ්‍යතාන්ත්‍රික ප්‍රයත්නයකින් පසු ශ්‍රී ලංකාව එක්සත් ජාතීන්ගේ සංවිධානයේ නිල සාමාජිකයෙකු බවට පත්විය."),
    q(T, "1956 දී සම්බුද්ධ ජයන්තිය (2500 වන බුද්ධ ජයන්තිය) නිමිත්තෙන් බණ්ඩාරනායක රජය විසින් ආරම්භ කළ දැවැන්ත බෞද්ධ ශාස්ත්‍රීය කර්තව්‍යය කුමක්ද?", "සිංහල ත්‍රිපිටක පරිවර්තනය සහ බෞද්ධ විශ්වකෝෂය සම්පාදනය කිරීම", "විහාරස්ථාන වැසීම", "පාසල් රජයට ගැනීම", "මහා සෑය තැනීම", "බුද්ධ ජයන්ති කමිටුව මගින් ත්‍රිපිටකය සිංහලට පරිවර්තනය කිරීම සහ ධර්ම ප්‍රචාරය රාජ්‍ය අනුග්‍රහයෙන් සිදු කෙරිණි."),
    q(T, "1958 දී ශ්‍රී ලංකාවේ ගොවි ජනතාවට ඉඩම් හිමිකාරිත්වය හා අඳ ගොවි අයිතිවාසිකම් තහවුරු කරමින් සම්මත කළ පනත කුමක්ද?", "1958 කුඹුරු පනත (Paddy Lands Act of 1958)", "ඉඩම් පනත", "මුඩුබිම් පනත", "ධාන්‍ය පනත", "කෘෂිකර්ම අමාත්‍ය පිලිප් ගුණවර්ධන මහතා විසින් ගෙනා මෙම පනත මගින් අඳ ගොවියා ඉඩම් හිමියාගේ සූරාකෑමෙන් නිදහස් කර අස්වැන්නෙන් සාධාරණ කොටසක් තහවුරු කළේය."),
    q(T, "1958 දී සිංහල-දෙමළ ජාතික අසමගිය සමනය කර දෙමළ භාෂාවට සාධාරණ තැනක් ලබාදීමට අත්සන් තැබූ ඓතිහාසික ගිවිසුම කුමක්ද?", "බණ්ඩා-චෙල්වා ගිවිසුම 1957 (Bandaranaike-Chelvanayakam Pact)", "ඩඩ්ලි-චෙල්වා ගිවිසුම", "සිරිමා-ශාස්ත්‍රි ගිවිසුම", "ඉන්දු-ලංකා ගිවිසුම", "උතුරු සහ නැගෙනහිර පළාත්වල දෙමළ භාෂාව පරිපාලන භාෂාවක් ලෙස භාවිතයටත් ප්‍රාදේශීය සභා ඇතිකිරීමටත් එකඟ වූ නමුත් දැඩි විරෝධතා හමුවේ එය ඉරා දැමීමට සිදුවිය."),
    q(T, "1965 දී ඩඩ්ලි සේනානායක සහ එස්. ජේ. වී. චෙල්වනායගම් අතර අත්සන් කරන ලද ගිවිසුම කුමක්ද?", "ඩඩ්ලි-චෙල්වා ගිවිසුම (Dudley-Chelvanayakam Pact of 1965)", "බණ්ඩා-චෙල්වා ගිවිසුම", "සිරිමා-ශාස්ත්‍රි ගිවිසුම", "ඉන්දු-ලංකා ගිවිසුම", "දිස්ත්‍රික් සභා පිහිටුවීම සහ උතුරු නැගෙනහිර දෙමළ භාෂා භාවිතය පිළිබඳ මෙම ගිවිසුමද විපක්ෂයේ විරෝධතා නිසා ක්‍රියාත්මක කිරීමට නොහැකි විය."),
    q(T, "1965-1970 ඩඩ්ලි සේනානායක රජය විසින් රට සහලින් ස්වයංපෝෂිත කිරීම සඳහා දියත් කළ මහා වැඩසටහන කුමක්ද?", "ගොවි රජු ව්‍යාපාරය සහ ආහාර වගා සංග්‍රාමය (Food Production Drive)", "කඩිනම් මහවැලි", "ගල්ඔය ව්‍යාපාරය", "කුඹුරු පනත", "නව වී ප්‍රභේද (H4) හඳුන්වා දෙමින් දේශීය වී අස්වැන්න වාර්තාගත ලෙස ඉහළ නැංවීමට ඩඩ්ලි සේනානායක මහතා සමත් විය."),
    q(T, "1970 දී පිහිටුවන ලද 'සමගි පෙරමුණු ආණ්ඩුවට' (United Front Government) අයත් වූ දේශපාලන පක්ෂ ත්‍රිත්වය මොනවාද?", "ශ්‍රී ලංකා නිදහස් පක්ෂය, ලංකා සමසමාජ පක්ෂය සහ කොමියුනිස්ට් පක්ෂය", "එජාපය, ශ්‍රීලනිපය සහ දෙමළ කොංග්‍රසය", "ජවිපෙ, එජාපය සහ සමසමාජය", "ෆෙඩරල් පක්ෂය, දෙමළ කොංග්‍රසය සහ මුස්ලිම් ලීගය", "සිරිමාවෝ බණ්ඩාරනායක මැතිනියගේ නායකත්වයෙන් තුනෙන් දෙකක බලයක් සහිතව සමාජවාදී සමගි පෙරමුණු ආණ්ඩුව බිහිවිය."),
    q(T, "1971 අප්‍රේල් මාසයේදී රෝහණ විජේවීරගේ නායකත්වයෙන් යුත් ජනතා විමුක්ති පෙරමුණ (JVP) විසින් දියත් කළ සිදුවීම කුමක්ද?", "1971 තරුණ සන්නද්ධ කැරැල්ල (1971 April Insurrection)", "හර්තාලය", "1915 කෝලාහලය", "මාතලේ කැරැල්ල", "රැකියා විරහිත ග්‍රාමීය තරුණයන් විසින් පොලිස් ස්ථාන 70 කට අධික සංඛ්‍යාවකට එකවර ප්‍රහාර එල්ල කරමින් රාජ්‍ය බලය ඇල්ලීමට උත්සාහ කළහ."),
    q(T, "1972 ප්‍රථම ජනරජ ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් බුද්ධාගමට ලබාදුන් ව්‍යවස්ථාපිත තත්ත්වය කුමක්ද?", "බුද්ධ ශාසනයට ප්‍රමුඛස්ථානය ලබාදීම සහ එය සුරක්ෂිත කර පෝෂණය කිරීම රජයේ වගකීමක් බවට පත්කිරීම", "රාජ්‍ය ආගම කිරීම", "ආගම් තහනම් කිරීම", "කිසිදු තැනක් නොදීම", "ව්‍යවස්ථාවේ 6 වන වගන්තිය (වර්තමාන 9 වන වගන්තිය) මගින් බුදුදහමට ප්‍රමුඛස්ථානය දෙන අතර අනෙක් සියලු ආගම්වලට නිදහස තහවුරු කරන ලදී."),
    q(T, "1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාව සම්මත කරගැනීම සඳහා පාර්ලිමේන්තු මන්ත්‍රීවරුන් රැස්වූ විශේෂ ස්ථානය කුමක්ද?", "කොළඹ රාජකීය ප්‍රාථමික විද්‍යාලයේ 'නව රඟහල' (Navarangahala)", "පාර්ලිමේන්තු ගොඩනැගිල්ල", "නිදහස් චතුරශ්‍රය", "ජනාධිපති මන්දිරය", "ආණ්ඩුක්‍රම සම්පාදක මණ්ඩලයක් (Constituent Assembly) ලෙස මන්ත්‍රීවරු නව රඟහලට රැස්වී මහජන අදහස් විමසා ව්‍යවස්ථාව සම්මත කළහ."),
    q(T, "1972 දී සම්මත කළ ඉඩම් ප්‍රතිසංස්කරණ පනත (Land Reform Act of 1972) මගින් පුද්ගලයෙකුට තබාගත හැකි උපරිම ඉඩම් සීමාව කීයද?", "අක්කර 50 කි (කුඹුරු ඉඩම් නම් අක්කර 25 කි)", "අක්කර 100 කි", "අක්කර 10 කි", "අක්කර 200 කි", "අක්කර 50 ට වැඩි සියලු ඉඩම් රජයට පවරා ගෙන ඉඩම් ප්‍රතිසංස්කරණ කොමිසම (LRC) යටතට පත් කරන ලදී."),
    q(T, "1975 දී සිරිමාවෝ බණ්ඩාරනායක රජය විසින් මෙරට විදේශිකයන් සතුවූ වැවිලි ආර්ථිකයට කළ දැවැන්ත මැදිහත්වීම කුමක්ද?", "බ්‍රිතාන්‍ය සමාගම් සතුවූ සියලු තේ, රබර් සහ පොල් වතු සම්පූර්ණයෙන්ම රජයට පවරා ගැනීම (ජනසතු කිරීම)", "වතු විකිණීම", "වතු වැසීම", "වතු පෞද්ගලීකරණය", "ජනවසම (JEDB) සහ රාජ්‍ය වැවිලි සංස්ථාව (SLSPC) පිහිටුවා විදේශීය වතු සමාගම්වල ඒකාධිකාරය අවසන් කරන ලදී."),
    q(T, "1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් ශ්‍රී ලංකාවේ නිල නාමය සංශෝධනය වූයේ කෙසේද?", "ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජය (Democratic Socialist Republic of Sri Lanka)", "ලංකා ඩොමීනියන් රාජ්‍යය", "ශ්‍රී ලංකා ජනරජය", "සිලෝන්", "1978 සැප්තැම්බර් 7 වන දින සිට ක්‍රියාත්මක වන පරිදි ශ්‍රී ලංකාවේ වර්තමාන නිල නාමය මෙය වේ."),
    q(T, "1982 දී ශ්‍රී ලංකාවේ නව පාර්ලිමේන්තු සංකීර්ණය ඓතිහාසික අගනුවරක් වූ කුමන නගරයේ ඉදිකර විවෘත කරන ලද්දේද?", "ශ්‍රී ජයවර්ධනපුර කෝට්ටේ දියවන්නා ඔය මැද", "කොළඹ ගාලුමුවදොර", "මහනුවර", "අනුරාධපුරය", "ජෙෆ්රි බාවාගේ ගෘහ නිර්මාණ සැලසුමකට අනුව දියවන්නා ඔය මැද දූපතක අලංකාර නව පාර්ලිමේන්තු මන්දිරය ඉදිකරන ලදී."),
    q(T, "1977 න් පසු විවෘත ආර්ථිකය යටතේ විදේශ ආයෝජන ආකර්ෂණය කරගැනීම සඳහා කටුනායක සහ බියගම පිහිටවූ විශේෂ කලාප මොනවාද?", "නිදහස් වෙළඳ කලාප හෙවත් ආයෝජන ප්‍රවර්ධන කලාප (FTZ / BOI)", "කෘෂිකාර්මික කලාප", "සංචාරක කලාප", "මහවැලි කලාප", "ඇඟලුම් සහ ඉලෙක්ට්‍රොනික භාණ්ඩ නිෂ්පාදනය කර අපනයනය කිරීම සඳහා බදු සහන සහිත නිදහස් වෙළඳ කලාප ආරම්භ විය."),
    q(T, "1987 ජූලි 29 වන දින ජේ. ආර්. ජයවර්ධන සහ රජීව් ගාන්ධි අතර අත්සන් තබන ලද ඓතිහාසික ගිවිසුම කුමක්ද?", "ඉන්දු-ලංකා සාම ගිවිසුම (Indo-Lanka Peace Accord 1987)", "සිරිමා-ශාස්ත්‍රි ගිවිසුම", "කච්චතිව් ගිවිසුම", "නොබැඳි ගිවිසුම", "උතුරු-නැගෙනහිර ගැටුම විසඳීම සඳහා ඉන්දීය සාමසාධක හමුදාව (IPKF) මෙරටට ගෙන්වීමට සහ පළාත් සභා ක්‍රමය පිහිටුවීමට මින් එකඟ විය."),
    q(T, "ඉන්දු-ලංකා ගිවිසුමේ ප්‍රතිඵලයක් ලෙස 1987 දී ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවට එක්කළ ඓතිහාසික සංශෝධනය කුමක්ද?", "13 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය (13th Amendment)", "10 වන සංශෝධනය", "17 වන සංශෝධනය", "19 වන සංශෝධනය", "බලය විමධ්‍යගත කිරීම සඳහා පළාත් සභා (Provincial Councils) ස්ථාපිත කිරීම සහ දෙමළ භාෂාව රාජ්‍ය භාෂාවක් බවට පත්කිරීම 13 වන සංශෝධනයෙන් සිදු විය."),
    q(T, "1987-1989 භීෂණ සමයේදී ඉන්දු-ලංකා ගිවිසුමට සහ ඉන්දීය හමුදා පැමිණීමට එරෙහිව දකුණේ පැනනැගුණු සන්නද්ධ කැරැල්ල කුමක්ද?", "දෙවන ජවිපෙ තරුණ කැරැල්ල (Second JVP Insurrection)", "1971 කැරැල්ල", "1848 කැරැල්ල", "හර්තාලය", "දේශප්‍රේමී ජනතා ව්‍යාපාරය නමින් දියත් වූ මෙම සන්නද්ධ ගැටුම දහස් ගණනක් ජීවිත විනාශ කරමින් 1989 අගභාගයේදී හමුදාව විසින් මර්දනය කරන ලදී."),
    q(T, "1994 සිට 2005 දක්වා ශ්‍රී ලංකාවේ ප්‍රථම විධායක ජනාධිපතිවරිය ලෙස කටයුතු කළ නායිකාව කවුද?", "චන්ද්‍රිකා බණ්ඩාරනායක කුමාරතුංග (Chandrika Bandaranaike Kumaratunga)", "සිරිමාවෝ බණ්ඩාරනායක", "විවියන් ගුණවර්ධන", "හේමා ප්‍රේමදාස", "එස්. ඩබ්ලිව්. ආර්. ඩී. බණ්ඩාරනායක සහ සිරිමාවෝ බණ්ඩාරනායක යුවළගේ දියණිය වූ චන්ද්‍රිකා කුමාරතුංග මහත්මිය දෙවරක්ම ජනාධිපති ධුරයට තේරී පත් වූවාය."),
    q(T, "දශක තුනකට ආසන්න කාලයක් ශ්‍රී ලංකාවේ පැවති උතුරු-නැගෙනහිර බෙදුම්වාදී එල්ටීටීඊ (LTTE) ත්‍රස්තවාදය යුදමය වශයෙන් මුළුමනින්ම පරාජය කළ දිනය කුමක්ද?", "2009 මැයි 18 වන දින (May 18, 2009)", "2002 පෙබරවාරි 22", "1987 ජූලි 29", "1994 අගෝස්තු 16", "නන්දිකඩාල් කලපුව ආශ්‍රිත අවසන් සටනේදී ත්‍රස්තවාදී නායකයන් විනාශ වීමත් සමග මුළු ශ්‍රී ලංකාවම එක්සේසත් වී සාමය උදාවිය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රජාතන්ත්‍රවාදී පාලන ව්‍යුහය තුළ නීතියේ ආධිපත්‍යය, මානව හිමිකම් සහ ජනතා පරමාධිපත්‍යය ආරක්ෂා කරන උත්තරීතර ලියවිල්ල කුමක්ද?", "ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජයේ ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "දණ්ඩ නීති සංග්‍රහය", "මහාවංශය", "රාජකීය ප්‍රකාශනය", "සියලු පුරවැසියන්ගේ මූලික අයිතිවාසිකම් සහ රාජ්‍ය පාලන බලතල විග්‍රහ කරන මූලික නීතිය ආණ්ඩුක්‍රම ව්‍යවස්ථාවයි."),
    q(T, "ප්‍රාග් ඓතිහාසික යුගයේ සිට නූතන යුගය දක්වා ශ්‍රී ලංකා ඉතිහාසය හැදෑරීමෙන් සිසුන්ට ලැබෙන උසස්ම ඵලය කුමක්ද?", "තම මව්බිමේ අභිමානවත් උරුමය හඳුනාගෙන ජාතික සමගියෙන් හා දේශප්‍රේමයෙන් යුතුව අනාගතය ගොඩනැගීමට පෙළඹීම", "අතීතය ගැන පමණක් සිතීම", "අන්‍ය ජාතීන්ට වෛර කිරීම", "විභාගය සමත්වීම පමණක්", "ශ්‍රී ලංකාවේ පොහොසත් ඓතිහාසික අත්දැකීම් නූතන ලෝකයේ ශක්තිමත්, සාමකාමී හා සෞභාග්‍යමත් ජාතියක් ලෙස ඉදිරියට යාමට මගපෙන්වයි."),
    q(T, "1910 මැකලම් ආණ්ඩුක්‍රමයේ උගත් ලාංකික ආසනය දිනාගත් ශ්‍රීමත් පොන්නම්බලම් රාමනාදන් මහතා පරාජය කළ ප්‍රතිවාදියා කවුද?", "වෛද්‍ය මාකස් ප්‍රනාන්දු මහතා", "සර් ජේම්ස් පීරිස්", "සර් පොන්නම්බලම් අරුණාචලම්", "ඊ. ඩබ්ලිව්. පෙරේරා", "1911 දී පැවති ඡන්ද විමසීමේදී උගත් ලාංකික ආසනය සඳහා වෛද්‍ය මාකස් ප්‍රනාන්දු පරාජය කරමින් පොන්නම්බලම් රාමනාදන් මහතා ජයග්‍රහණය කළේය."),
    q(T, "1911 දී උගත් ලාංකික ආසනය සඳහා පැවති ඡන්ද විමසීමේදී ඡන්දය ප්‍රකාශ කිරීමට හිමිකම් ලැබූ ලාංකිකයන් සංඛ්‍යාව කොපමණද?", "දළ වශයෙන් 2,938 ක් පමණ සුළු පිරිසක්", "ලක්ෂයකට අධික පිරිසක්", "මිලියන 2 ක් පමණ", "50,000 කට අධික පිරිසක්", "උසස් අධ්‍යාපන සහ ඉහළ ධන සීමා පනවා තිබූ බැවින් ඡන්ද හිමිකම ලැබුණේ සමස්ත ජනගහනයෙන් ඉතා සුළු පිරිසකට පමණි."),
    q(T, "1915 සිංහල-මුස්ලිම් කෝලාහලය මැඩපැවැත්වීමට පැනවූ මිලිටරි නීතිය යටතේ අසාධාරණ ලෙස වෙඩි තබා මරාදැමූ ජාතික වීරවරයා කවුද?", "එඩ්වඩ් හෙන්රි පේද්‍රිස් මහතා", "ඩී. එස්. සේනානායක", "ඩී. බී. ජයතිලක", "කැප්පෙටිපොළ නිලමේ", "බ්‍රිතාන්‍ය ආණ්ඩුකාර රොබට් චාමර්ස්ගේ යුද නීතිය යටතේ 27 හැවිරිදි එඩ්වඩ් හෙන්රි පේද්‍රිස් තරුණයා අසාධාරණ ලෙස මරා දැමිණි."),
    q(T, "1915 කෝලාහල සමයේ සිරගත කරන ලද සිංහල නායකයන් බේරාගැනීම සඳහා සිය ජීවිතය පරදුවට තබා ලන්ඩනය බලා ගිය දේශප්‍රේමියා කවුද?", "ඊ. ඩබ්ලිව්. පෙරේරා මහතා", "සර් ජෝන් කොතලාවල", "එස්. ඩබ්. ආර්. ඩී. බණ්ඩාරනායක", "එෆ්. ආර්. සේනානායක", "ඊ. ඩබ්ලිව්. පෙරේරා මහතා බ්‍රිතාන්‍ය සබ්මැරීන ප්‍රහාර මැද සාගර තරණය කර ලන්ඩනයට ගොස් සාක්ෂි ඉදිරිපත් කළේය."),
    q(T, "ඊ. ඩබ්ලිව්. පෙරේරා මහතා බ්‍රිතාන්‍ය පාලකයන්ගේ ම්ලේච්ඡ ක්‍රියා පිළිබඳ රහසිගත ආයාචනය ලන්ඩනයට ගෙන ගියේ කෙසේද?", "තම පාවහන් (සපත්තු) අඩියේ සඟවාගෙන", "තොප්පිය ඇතුළත රඳවාගෙන", "රාජ්‍ය තාන්ත්‍රික ගමන් මල්ලක", "පොත් කවරයක් තුළ අලවාගෙන", "බ්‍රිතාන්‍ය ඔත්තුකරුවන්ට හසු නොවනු පිණිස වෙඩි තැබීම් පිළිබඳ ආයාචනා පත්‍රය සපත්තු අඩියේ සඟවාගෙන ගියේය."),
    q(T, "1917 දී ලංකාවේ සියලුම ජාතීන් නියෝජනය කරමින් බිහිවූ ලංකා ප්‍රතිසංස්කරණ ලීගය (Ceylon Reform League) පිහිටුවීමේ ප්‍රමුඛයා කවුද?", "ශ්‍රීමත් පොන්නම්බලම් අරුණාචලම් මහතා", "සර් ඒ. එෆ්. මොලමුරේ", "ඩී. එස්. සේනානායක", "ආචාර්ය එන්. එම්. පෙරේරා", "ජාති, ආගම් භේදයකින් තොරව ව්‍යවස්ථා ප්‍රතිසංස්කරණ දිනාගැනීම සඳහා අරුණාචලම් මහතාගේ නායකත්වයෙන් මෙය පිහිටුවන ලදී."),
    q(T, "1919 දෙසැම්බර් 11 වන දින ආරම්භ කරන ලද ලංකා ජාතික සංගමයේ (Ceylon National Congress) ප්‍රථම සභාපතිවරයා කවුද?", "ශ්‍රීමත් පොන්නම්බලම් අරුණාචලම් මහතා", "ශ්‍රීමත් ඩී. බී. ජයතිලක", "සර් ජේම්ස් පීරිස්", "එෆ්. ආර්. සේනානායක", "සිංහල හා දෙමළ නායකයන්ගේ ඒකාබද්ධ එකමුතුවෙන් බිහිවූ ලංකා ජාතික සංගමයේ මුල්ම සභාපතිවරයා වූයේ අරුණාචලම් මැතිතුමාය."),
    q(T, "ලංකා ජාතික සංගමයේ ප්‍රථම සම-ලේකම් ධුර දැරූ නායකයන් දෙපළ කවුරුන්ද?", "සර් ජේම්ස් පීරිස් සහ කේ. බාලසිංහම්", "ඩී. එස්. සේනානායක සහ ඊ. ඩබ්ලිව්. පෙරේරා", "පොන්නම්බලම් රාමනාදන් සහ මාකස් ප්‍රනාන්දු", "ඩී. බී. ජයතිලක සහ ඒ. ඊ. ගුණසිංහ", "කොළඹ පැවති ආරම්භක මහා සමුළුවේදී ජේම්ස් පීරිස් සහ කේ. බාලසිංහම් ලේකම්වරුන් ලෙස පත් කරගන්නා ලදී."),
    q(T, "1920 මැනිං ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණයේ ප්‍රධානතම සුවිශේෂී ලක්ෂණය කුමක්ද?", "ව්‍යවස්ථාදායක සභාවේ නිල නොලත් මන්ත්‍රී සංඛ්‍යාව නිලලත් මන්ත්‍රී සංඛ්‍යාවට වඩා වැඩිවීම", "සර්වජන ඡන්ද බලය ලැබීම", "පූර්ණ නිදහස හිමිවීම", "අග්‍රාමාත්‍ය ධුරයක් ඇතිවීම", "ප්‍රථම වරට නිල නොලත් ලාංකික මන්ත්‍රීවරුන්ට බහුතර බලයක් හිමිවූ නමුත් විධායක බලය ආණ්ඩුකාරවරයා සතුවම පැවතිණි."),
    q(T, "1924 මැනිං-ඩෙවොන්ෂයර් ආණ්ඩුක්‍රමය යටතේ ව්‍යවස්ථාදායක සභාවේ මුළු මන්ත්‍රී සංඛ්‍යාව කීයක් දක්වා වැඩි කෙරිණිද?", "මන්ත්‍රීවරුන් 49 ක් දක්වා", "මන්ත්‍රීවරුන් 101 ක් දක්වා", "මන්ත්‍රීවරුන් 25 ක් දක්වා", "මන්ත්‍රීවරුන් 168 ක් දක්වා", "මන්ත්‍රීවරුන් 49 න් 37 දෙනෙකුම නිල නොලත් මන්ත්‍රීවරුන් වූ අතර 34 දෙනෙකු ඡන්දයෙන් තේරී පත් විය."),
    q(T, "1924 ව්‍යවස්ථාදායක සභාවේ මුලසුන හෙබවීම සඳහා ආණ්ඩුකාරවරයා වෙනුවට පත්කළ ප්‍රථම ලාංකික උප සභාපතිවරයා කවුද?", "සර් ජේම්ස් පීරිස් මහතා", "සර් ඒ. එෆ්. මොලමුරේ", "ඩී. බී. ජයතිලක", "පී. රාමනාදන්", "ව්‍යවස්ථාදායක සභාවේ මුලසුන ආණ්ඩුකාරවරයාගෙන් ඉවත්ව ලාංකික උප සභාපතිවරයෙකුට හිමිවීම ඓතිහාසික ජයග්‍රහණයක් විය."),
    q(T, "1924 දී යාපනයේ පිහිටුවන ලද තරුණ කොංග්‍රසය (Jaffna Youth Congress) ආරම්භ කළ ප්‍රමුඛ නායකයා කවුද?", "හැන්ඩි පේරින්පනායගම් මහතා", "එස්. ජේ. වී. චෙල්වනායගම්", "ජී. GG. පොන්නම්බලම්", "කේ. බාලසිංහම්", "මහත්මා ගාන්ධිගේ ප්‍රතිපත්ති අනුගමනය කරමින් ලංකාවේ ප්‍රගතිශීලී තරුණ පරපුර සංවිධානය කිරීමට මොහු පෙරමුණ ගත්තේය."),
    q(T, "බ්‍රිතාන්‍ය පාලනයෙන් ශ්‍රී ලංකාවට පූර්ණ ස්වාධීනත්වය (පූර්ණ ස්වරාජ්‍යය) ලබාගත යුතු යැයි ප්‍රථම වරට යෝජනා කළ දේශීය සංවිධානය කුමක්ද?", "යාපනයේ තරුණ කොංග්‍රසය (Jaffna Youth Congress)", "ලංකා ජාතික සංගමය", "ලංකා මහජන සභාව", "පරම විඥානාර්ථ බෞද්ධ සමාගම", "1924 දී යාපනයේ තරුණ කොංග්‍රසය අධිරාජ්‍යවාදයෙන් පූර්ණ නිදහස ඉල්ලා රට පුරා දැවැන්ත උද්ඝෝෂණයක් ගොඩනැගීය."),
    q(T, "1927 දී ලංකාවට පැමිණි ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණ කොමිසමේ සභාපතිත්වය දැරූ බ්‍රිතාන්‍ය සාමිවරයා කවුද?", "ඩොනමෝර් සාමිවරයා (Earl of Donoughmore)", "සෝල්බරි සාමිවරයා", "කෝල්බෲක් සාමිවරයා", "චෙම්ස්ෆර්ඩ් සාමිවරයා", "ඩොනමෝර් සාමි ප්‍රමුඛ සිව් පුද්ගල කොමිසම ලංකාවේ ව්‍යවස්ථා ගැටලු අධ්‍යයනය කර සර්වජන ඡන්දය නිර්දේශ කළේය."),
    q(T, "ඩොනමෝර් කොමිසම හමුවේ සාක්ෂි දෙමින් ලංකාවේ කාන්තාවන්ට ද ඡන්ද අයිතිය ලබාදිය යුතු බවට දැඩිව පෙනී සිටි සංවිධානය කුමක්ද?", "ලංකා කාන්තා ඡන්ද බල සංගමය (Women Franchise Union)", "ලංකා ගුරු සංගමය", "මහා බෝධි සමාගම", "තරුණ බෞද්ධ සංගමය", "මල්ලිකා කුලරත්න, සුනේත්‍රා විජේසිංහ ඇතුළු ප්‍රමුඛ කාන්තා නායිකාවන් කාන්තා ඡන්ද අයිතිය දිනාගැනීමට සටන් කළහ."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමය මගින් ලංකාවේ පිහිටුවන ලද නව ව්‍යවස්ථාදායක ආයතනය හැඳින්වූයේ කුමන නමකින්ද?", "රාජ්‍ය මන්ත්‍රණ සභාව (State Council)", "නියෝජිත මන්ත්‍රී මණ්ඩලය", "ජාතික රාජ්‍ය සභාව", "සෙනෙට් සභාව", "1931 සිට 1947 දක්වා මෙරට නීති සම්පාදන සහ විධායක ආයතනය ලෙස රාජ්‍ය මන්ත්‍රණ සභාව ක්‍රියාත්මක විය."),
    q(T, "ඩොනමෝර් ක්‍රමය යටතේ රාජ්‍ය මන්ත්‍රණ සභාවට මහජන ඡන්දයෙන් ඍජුව තේරී පත් වූ මුළු මන්ත්‍රී සංඛ්‍යාව කීයද?", "මන්ත්‍රීවරුන් 50 ක්", "මන්ත්‍රීවරුන් 101 ක්", "මන්ත්‍රීවරුන් 30 ක්", "මන්ත්‍රීවරුන් 75 ක්", "දිවයින පුරා ආසන 50 කින් සර්වජන ඡන්ද බලයෙන් මන්ත්‍රීවරුන් 50 දෙනෙකු තෝරාපත් කරගන්නා ලදී."),
    q(T, "ඩොනමෝර් රාජ්‍ය මන්ත්‍රණ සභාවේ සමස්ත මන්ත්‍රී ධුර සංඛ්‍යාව නිවැරදිව දැක්වෙන සංයුතිය කුමක්ද?", "61 කි (තේරීපත් 50, නම්කළ 8, රාජ්‍ය නිලධාරීන් 3)", "50 කි (සියල්ල ඡන්දයෙන්)", "100 කි (තේරීපත් 80, නම්කළ 20)", "30 කි (තේරීපත් 15, පත්කළ 15)", "සුළුතර නියෝජනය රැකීමට ආණ්ඩුකාරවරයා නම්කළ 8 දෙනා සහ රාජ්‍ය නිලධාරීන් තිදෙනා එක්ව මුළු සභාව 61 ක් විය."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ අමාත්‍යාංශ පාලනය සඳහා හඳුන්වා දුන් අද්විතීය ආණ්ඩුක්‍රම යාන්ත්‍රණය කුමක්ද?", "විධායක කාරක සභා ක්‍රමය (Executive Committee System)", "කැබිනට් ක්‍රමය", "ජනාධිපති ක්‍රමය", "රාජ්‍ය ආරක්ෂක කවුන්සිලය", "මන්ත්‍රීවරුන්ට පාලන අත්දැකීම් ලබාදීම සඳහා එක් එක් කාරක සභාවට අමාත්‍යාංශ පරිපාලනය පැවරූ ස්විට්සර්ලන්ත ආභාසය ලත් ක්‍රමයකි."),
    q(T, "ඩොනමෝර් රාජ්‍ය මන්ත්‍රණ සභාව තුළ පිහිටුවන ලද විධායක කාරක සභා සංඛ්‍යාව කීයද?", "කාරක සභා 7 කි", "කාරක සභා 10 කි", "කාරක සභා 4 කි", "කාරක සභා 12 කි", "දේශීය ආදායම්, කෘෂිකර්ම, අධ්‍යාපනය, සෞඛ්‍ය, කම්කරු, පළාත් පාලන සහ සන්නිවේදන යන විෂයයන් සඳහා කාරක සභා 7 ක් පිහිටුවිණි."),
    q(T, "ඩොනමෝර් ආණ්ඩුක්‍රමයේ විධායක කාරක සභාවලට අයත් නොවූ, බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයාට සෘජුවම වගකී නිලධාරීන් තිදෙනා හැඳින්වූයේ කෙසේද?", "රාජ්‍ය නිලධාරීන් තිදෙනා (Three Officers of State)", "විධායක ඇමතිවරු තිදෙනා", "ත්‍රිවිධ හමුදාපතිවරු", "ස්වාධීන කොමසාරිස්වරු", "රාජ්‍ය ලේකම්, මුදල් ලේකම් සහ නීති ලේකම් යන තිදෙනා ප්‍රධාන විධායක නිලධාරීන් ලෙස කටයුතු කළහ."),
    q(T, "ඩොනමෝර් පාලන ක්‍රමය තුළ රාජ්‍ය නිලධාරීන් තිදෙනා භාරව පැවති විෂය ක්ෂේත්‍ර තුන මොනවාද?", "රාජ්‍ය ආරක්ෂාව හා විදේශ කටයුතු, මුදල් පරිපාලනය, නීති කටයුතු", "කෘෂිකර්මය, සෞඛ්‍යය, අධ්‍යාපනය", "ප්‍රවාහනය, වාරිමාර්ග, විදුලිබලය", "වෙළඳාම, තැපැල්, කර්මාන්ත", "රාජ්‍යයේ මූලික ආරක්ෂක, මූල්‍ය හා නෛතික බලතල බ්‍රිතාන්‍ය කිරීටයේ නියෝජිතයන් තිදෙනා අත රඳවා තබා ගන්නා ලදී."),
    q(T, "ඩොනමෝර් රාජ්‍ය මන්ත්‍රණ සභාවේ ප්‍රථම කථානායකවරයා (Speaker) ලෙස තේරී පත් වූයේ කවුද?", "සර් ඒ. එෆ්. මොලමුරේ මහතා", "සර් ජේම්ස් පීරිස්", "ඩී. එස්. සේනානායක", "ඩී. බී. ජයතිලක", "1931 දී රාජ්‍ය මන්ත්‍රණ සභාව ආරම්භයේදීම සර් ඒ. එෆ්. මොලමුරේ ප්‍රථම කථානායක ධුරයට තේරී පත් විය."),
    q(T, "ශ්‍රී ලංකාවේ ව්‍යවස්ථාදායක ඉතිහාසයේ ප්‍රථම මන්ත්‍රීවරිය ලෙස 1931 දී රුවන්වැල අතුරු මැතිවරණයෙන් තේරී පත් වූයේ කවුද?", "ඇඩ්ලින් මොලමුරේ ආර්යාව", "ෆ්ලෝරන්ස් සේනානායක", "විවියන් ගුණවර්ධන", "සිරිමාවෝ බණ්ඩාරනායක", "සර්වජන ඡන්ද බලයේ ප්‍රතිඵලයක් ලෙස මෙරට ව්‍යවස්ථාදායකයට පත් වූ ප්‍රථම කාන්තා නියෝජිතවරිය ඇඩ්ලින් මොලමුරේ මහත්මියයි."),
    q(T, "ලංකාවේ ප්‍රථම විධිමත් කම්කරු වෘත්තීය සමිතිය වූ ලංකා කම්කරු සංගමය (Ceylon Labour Union) 1922 දී පිහිටුවූ කම්කරු නායකයා කවුද?", "ඒ. ඊ. ගුණසිංහ මහතා", "ආචාර්ය එන්. එම්. පෙරේරා", "පිලිප් ගුණවර්ධන", "පී. කන්දයියා", "කොළඹ වරාය, දුම්රිය හා නාගරික කම්කරුවන් සංවිධානය කරමින් මෙරට කම්කරු ව්‍යාපාරයේ පියා ලෙස ඒ. ඊ. ගුණසිංහ කටයුතු කළේය."),
    q(T, "ශ්‍රී ලංකාවේ ප්‍රථම වතාවට මැයි දින පෙළපාලියක් (May Day Rally) 1927 දී කොළඹදී සංවිධානය කළ කම්කරු නායකයා කවුද?", "ඒ. ඊ. ගුණසිංහ මහතා", "ඩී. එස්. සේනානායක", "කොල්වින් ආර්. ද සිල්වා", "ලෙස්ලි ගුණවර්ධන", "කම්කරු අයිතිවාසිකම් වෙනුවෙන් හඬ නගමින් ප්‍රථම මැයි දින පෙළපාලිය සහ රැළිය කොළඹදී පැවැත්වූයේ ඒ. ඊ. ගුණසිංහ මහතාය."),
    q(T, "1933 දී බ්‍රිතාන්‍ය පොපි මල් විකිණීමට විරෝධය පාමින් මෙරට අධිරාජ්‍ය විරෝධීන් ආරම්භ කළ ව්‍යාපාරය කුමක්ද?", "සූරියමල් ව්‍යාපාරය (Suriya-Mal Movement)", "අමද්‍යප ව්‍යාපාරය", "ස්වභාෂා ව්‍යාපාරය", "හර්තාල ව්‍යාපාරය", "පළමු ලෝක යුද්ධයේ බ්‍රිතාන්‍ය සොල්දාදුවන් වෙනුවෙන් මුදල් එකතු කරන පොපි මල් වෙනුවට මෙරට දුගීන් වෙනුවෙන් සූරියමල් විකුණන ලදී."),
    q(T, "සූරියමල් ව්‍යාපාරයේ ප්‍රථම සභාපතිනිය ලෙස පත් වූ ප්‍රමුඛ සමාජ ක්‍රියාකාරිනිය කවුද?", "ඩොරින් වික්‍රමසිංහ මහත්මිය", "විවියන් ගුණවර්ධන", "සෙලස්ටිනා ඩයස්", "කුසුමා ගුණවර්ධන", "ලංකාවේ සමාජවාදී හා අධිරාජ්‍ය විරෝධී ව්‍යාපාරවල මුල්පෙළේ ක්‍රියාකාරිනියක් වූ ඇය පසුව පාර්ලිමේන්තු මන්ත්‍රීවරියක් ලෙස ද පත්වූවාය."),
    q(T, "1934-1935 කාලයේ ලංකාවේ කැලණි නිම්නය හා සබරගමුව ආශ්‍රිතව ලක්ෂ සංඛ්‍යාත ජනතාවක් පීඩාවට පත්කළ වසංගතය කුමක්ද?", "මැලේරියා වසංගතය", "වසූරිය වසංගතය", "කොලරාව", "මහාමාරිය", "නියඟය හා සාගතය සමග පැමිණි මැලේරියා වසංගතයෙන් 80,000 කට අධික ජනකායක් මියගිය අතර තරුණ වාමාංශිකයෝ සහන සේවා සැලසූහ."),
    q(T, "1935 දෙසැම්බර් 18 වන දින මෙරට ප්‍රථම ලියාපදිංචි දේශපාලන පක්ෂය ලෙස පිහිටුවන ලද පක්ෂය කුමක්ද?", "ලංකා සමසමාජ පක්ෂය (LSSP)", "ශ්‍රී ලංකා නිදහස් පක්ෂය", "එක්සත් ජාතික පක්ෂය", "කොමියුනිස්ට් පක්ෂය", "පූර්ණ ජාතික නිදහස සහ සමාජවාදී ආර්ථිකයක් ස්ථාපිත කිරීම අරමුණු කරගත් මෙරට පැරණිතම දේශපාලන පක්ෂය මෙය වේ."),
    q(T, "ලංකා සමසමාජ පක්ෂයේ (LSSP) ප්‍රථම සභාපතිවරයා ලෙස තේරී පත් වූයේ කවුද?", "ආචාර්ය කොල්වින් ආර්. ද සිල්වා", "ආචාර්ය එන්. එම්. පෙරේරා", "පිලිප් ගුණවර්ධන", "ලෙස්ලි ගුණවර්ධන", "තරුණ නීතිඥයෙකු වූ ආචාර්ය කොල්වින් ආර්. ද සිල්වා මහතා පක්ෂයේ ප්‍රථම සභාපතිවරයා ලෙස තේරී පත් විය."),
    q(T, "1936 දෙවන රාජ්‍ය මන්ත්‍රණ සභාවේ සභානායක හා ස්වදේශ කටයුතු භාර අමාත්‍යවරයා ලෙස කටයුතු කළ ප්‍රවීණ රාජ්‍ය තාන්ත්‍රිකයා කවුද?", "ශ්‍රීමත් ඩී. බී. ජයතිලක මහතා", "සර් ජෝන් කොතලාවල", "ඊ. ඩබ්ලිව්. පෙරේරා", "එස්. ඩබ්. ආර්. ඩී. බණ්ඩාරනායක", "ඩී. බී. ජයතිලක මැතිතුමා සභානායක ධුරය හොබවමින් දේශීය පරිපාලනය හා අධ්‍යාපනය නගාසිටුවීමට පුරෝගාමී විය."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේදී බ්‍රිතාන්‍ය රජය විසින් ලංකාවේ ආරක්ෂාව හා සිවිල් පාලනය සඳහා පත්කළ යුද ආඥාපතිවරයා කවුද?", "අද්මිරාල් ශ්‍රීමත් ජෙෆ්රි ලයිටන් (Sir Geoffrey Layton)", "ජනරාල් ආතර් වෙලස්ලි", "මවුන්ට්බැටන් සාමි", "මේජර් ජනරාල් ඩොනමෝර්", "1942 දී යුද කවුන්සිලයක් පිහිටුවා ලංකාවේ සියලුම පරිපාලන හා යුදමය බලතල ලයිටන් ආඥාපතිවරයා යටතට පත් කෙරිණි."),
    q(T, "1942 අප්‍රේල් මාසයේදී ජපන් අධිරාජ්‍ය ගුවන් හමුදාව විසින් බෝම්බ හෙළා ප්‍රහාර එල්ල කරන ලද ශ්‍රී ලංකාවේ ප්‍රධාන වරාය නගර දෙක මොනවාද?", "කොළඹ සහ ත්‍රිකුණාමලය", "ගාල්ල සහ හම්බන්තොට", "මඩකලපුව සහ යාපනය", "මන්නාරම සහ මීගමුව", "1942 අප්‍රේල් 5 (පාස්කු ඉරිදා) කොළඹටත්, අප්‍රේල් 9 දින ත්‍රිකුණාමල නාවික තටාකාංගනයටත් ජපන් ප්‍රහාර එල්ල විය."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේ අග්නිදිග ආසියානු මිත්‍ර හමුදා උත්තරීතර මූලස්ථානය (SEAC) පිහිටුවා තිබුණේ ලංකාවේ කුමන ස්ථානයේද?", "මහනුවර පේරාදෙණිය උද්භිද උද්‍යානයේ", "කොළඹ කොටුව යුද හමුදා මූලස්ථානයේ", "ත්‍රිකුණාමලය කොටුවේ", "දියතලාව හමුදා කඳවුරේ", "අග්නිදිග ආසියාව පුරා මිත්‍ර හමුදා මෙහෙයුම් මෙහෙයවූ මූලස්ථානය පේරාදෙණිය මල්වත්තේ අතිශය රහසිගතව පවත්වාගෙන ගියේය."),
    q(T, "අග්නිදිග ආසියානු මිත්‍ර හමුදා උත්තරීතර අණදෙන නිලධාරියා ලෙස පේරාදෙණියේ සිට මෙහෙයුම් මෙහෙයවූ බ්‍රිතාන්‍ය නායකයා කවුද?", "ලුවී මවුන්ට්බැටන් සාමිවරයා (Lord Louis Mountbatten)", "වින්ස්ටන් චර්චිල්", "බර්නාඩ් මොන්ට්ගොමරි", "ඩග්ලස් මැක්ආතර්", "මවුන්ට්බැටන් සාමිවරයා ජපානයට එරෙහි බුරුම හා ආසියානු මෙහෙයුම් මෙරට සිට මෙහෙයවීය."),
    q(T, "දෙවන ලෝක යුද්ධ සමයේ ලංකා ආරක්ෂක බලකායේ සෙබළුන් පිරිසක් බ්‍රිතාන්‍ය අධිරාජ්‍යයට එරෙහිව කැරලි ගැසූ සුප්‍රකට ඓතිහාසික සිදුවීම කුමක්ද?", "1942 කොකෝස් දූපත් කැරැල්ල (Cocos Islands Mutiny)", "මාතලේ කැරැල්ල", "1915 කැරැල්ල", "සීපෝයි කැරැල්ල", "ඉන්දියන් සාගරයේ කොකෝස් දූපතේ මුර සංචාරයේ යෙදී සිටි ලාංකික සෙබළු පිරිසක් බ්‍රිතාන්‍ය පාලනයට එරෙහිව කැරලි ගැසූහ."),
    q(T, "කොකෝස් දූපත් කැරැල්ලට නායකත්වය දීම හේතුවෙන් බ්‍රිතාන්‍යයන් විසින් මරණ දණ්ඩනයට පමුණුවන ලද ලාංකික වීරවරයා කවුද?", "බොම්බාඩියර් ග්‍රේෂන් ප්‍රනාන්දු", "සැරයන් සිල්වා", "කෝප්‍රල් පෙරේරා", "කැප්ටන් ජයවර්ධන", "දෙවන ලෝක යුද්ධ සමයේ බ්‍රිතාන්‍ය පොදුරාජ්‍ය මණ්ඩල හමුදාවක කැරලි ගැසීම වෙනුවෙන් මරණ දණ්ඩනය ලැබූ එකම සොල්දාදුවා මොහුය."),
    q(T, "1944 දී ලංකාවට නව ආණ්ඩුක්‍රමයක් සැකසීම සඳහා බ්‍රිතාන්‍ය රජය විසින් පත් කරන ලද කොමිසමේ ප්‍රධානියා කවුද?", "සෝල්බරි සාමිවරයා (Lord Soulbury)", "ඩොනමෝර් සාමි", "කෝල්බෲක් සාමි", "ක්‍රිප්ස් සාමි", "සෝල්බරි කොමිසමේ නිර්දේශ මත 1947 දී වෙස්ට්මින්ස්ටර් සම්ප්‍රදායේ පාර්ලිමේන්තු ආණ්ඩුක්‍රමයක් ලංකාවට හඳුන්වා දෙන ලදී."),
    q(T, "සෝල්බරි කොමිසමට ඉදිරිපත් කළ ලාංකික ඇමති මණ්ඩල කෙටුම්පත (Ministers Draft) සැකසීමට ඩී. එස්. සේනානායකට සහාය වූ නීති විශාරදයා කවුද?", "ශ්‍රීමත් අයිවර් ජෙනිංස් (Sir Ivor Jennings)", "ශ්‍රීමත් ජෝන් කොතලාවල", "කොල්වින් ආර්. ද සිල්වා", "එච්. වී. පෙරේරා", "ලංකා විශ්වවිද්‍යාලයේ උපකුලපතිවරයා වූ ජෙනිංස් මහතා මෙරට ආණ්ඩුක්‍රම කෙටුම්පත් කිරීමේ ප්‍රධාන නීති උපදේශකයා විය."),
    q(T, "1947 සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් ලංකාවට හඳුන්වා දුන් ද්වි-මණ්ඩල පාර්ලිමේන්තුවේ මණ්ඩල දෙක මොනවාද?", "නියෝජිත මන්ත්‍රී මණ්ඩලය සහ සෙනෙට් සභාව", "රාජ්‍ය මන්ත්‍රණ සභාව සහ ජාතික රාජ්‍ය සභාව", "ව්‍යවස්ථාදායක සභාව සහ විධායක සභාව", "පාර්ලිමේන්තුව සහ පළාත් සභාව", "ජනතාව විසින් තෝරාපත් කරගන්නා නියෝජිත මන්ත්‍රී මණ්ඩලයකින් සහ උගත් විද්වතුන්ගෙන් සැදුම්ලත් සෙනෙට් මණ්ඩලයකින් පාර්ලිමේන්තුව සමන්විත විය."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රමය යටතේ සෙනෙට් සභාවේ (Senate) මුළු සාමාජික සංඛ්‍යාව කොපමණද?", "සෙනෙට් සභිකයන් 30 දෙනෙකි", "සෙනෙට් සභිකයන් 50 දෙනෙකි", "සෙනෙට් සභිකයන් 15 දෙනෙකි", "සෙනෙට් සභිකයන් 100 දෙනෙකි", "නියෝජිත මන්ත්‍රී මණ්ඩලයෙන් 15 දෙනෙකු සහ අග්‍රාණ්ඩුකාරවරයා විසින් 15 දෙනෙකු ලෙස සෙනෙට් සභිකයන් 30 දෙනෙකු පත් කරන ලදී."),
    q(T, "සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ සුළුතර ජාතීන්ගේ ආගමික හා සමාජ අයිතිවාසිකම් රැකගැනීම සඳහා ඇතුළත් කළ සුප්‍රකට වගන්තිය කුමක්ද?", "29(2) වගන්තිය", "13 වන වගන්තිය", "5 වන වගන්තිය", "42 වන වගන්තිය", "කිසිදු ආගමික හෝ ජාතික ප්‍රජාවකට අවාසි වන හෝ වාසි වන වෙනස්කම් සහිත නීති පැනවීම මෙමගින් සපුරා තහනම් විය."),
